UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f44d8e6ddb2deb7d71-en-1","language":"English","title":"Types of Business Services","topic_slug":"types-of-business-services","definition":"Service sector is the backbone of any economy as it provides employment to a large number of people. Business services are of two types: Internal services: These services are provided by a business enterprise to its own employees or departments. External services: These services are provided by a business enterprise to other business enterprises or to individuals.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f44d8e6ddb2deb7d71' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'types-of-business-services' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f54d8e6ddb2deb7d72-en-2","language":"English","title":"Emerging Modes of Business","topic_slug":"emerging-modes-of-business","definition":"e-business refers to the conduct of industry, trade, and commerce using computer networks. e-business includes not only e-commerce but also other electronically conducted business functions such as production, inventory management, product development, accounting, and finance, and human resource management. e-business is a more elaborate term than e-commerce and comprises various business functions and managerial activities like planning, organising, and controlling carried out over computer networks.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f54d8e6ddb2deb7d72' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'emerging-modes-of-business' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f54d8e6ddb2deb7d72-en-3","language":"English","title":"Scope of e-Business","topic_slug":"scope-of-e-business","definition":"The scope of e-business is quite vast and includes almost all types of business functions such as production, finance, marketing, and personnel administration. A network of computers is used for placing orders, monitoring production and delivery of components, and making payments. A firm may strengthen and improve its distribution system by exercising real-time control over its stock-in-transit as well as that with different middlemen in different locations.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f54d8e6ddb2deb7d72' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'scope-of-e-business' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f54d8e6ddb2deb7d72-en-4","language":"English","title":"e-Business versus e-Commerce","topic_slug":"e-business-versus-e-commerce","definition":"Although the terms e-business and e-commerce are used interchangeably, more precise definitions would distinguish between the two. e-business is a broader term than e-commerce and comprises various business functions and managerial activities. e-commerce is a subset of e-business and refers to the conduct of business transactions and functions electronically.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f54d8e6ddb2deb7d72' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'e-business-versus-e-commerce' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f54d8e6ddb2deb7d72-en-5","language":"English","title":"Business-to-Business (B2B) Commerce","topic_slug":"business-to-business-b2b-commerce","definition":"B2B commerce refers to the interactions between business firms and their suppliers or vendors. Creation of utilities or delivering value requires a business to interact with a number of other business firms which may be suppliers or vendors of diverse inputs. B2B commerce enables a business to be in touch with its suppliers and vendors on a round-the-clock basis.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f54d8e6ddb2deb7d72' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'business-to-business-b2b-commerce' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f54d8e6ddb2deb7d72-en-6","language":"English","title":"Business-to-Consumer (B2C) Commerce","topic_slug":"business-to-consumer-b2c-commerce","definition":"B2C commerce refers to the interactions between business firms and their customers. B2C commerce entails a wide gamut of product features to be tailor-made to suit the requirements of the individual customer. B2C commerce enables a business to be in touch with its customers on a round-the-clock basis.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f54d8e6ddb2deb7d72' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'business-to-consumer-b2c-commerce' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f54d8e6ddb2deb7d72-en-7","language":"English","title":"Benefits of e-Commerce","topic_slug":"benefits-of-e-commerce","definition":"e-commerce expands the marketplace to national and international markets. e-commerce facilitates ''pull'' supply chain management, competitive advantage over competitors, and proper time management and support business processes. e-commerce enables small firms to co-exist with big firms. e-commerce provides flexibility, competitive price/discounts/waive offs, more options and choices, and customised products. e-commerce enables quick and timely delivery of digitised products. e-commerce facilitates e-auctions and e-tenders. e-commerce enables interaction with consumers and wider outreach.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f54d8e6ddb2deb7d72' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'benefits-of-e-commerce' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f54d8e6ddb2deb7d72-en-8","language":"English","title":"Business-to-Consumer (B2C) Commerce: A One-Way Traffic?","topic_slug":"business-to-consumer-b2c-commerce-a-one-way-traffic","definition":"B2C commerce is not a one-way traffic, but rather a two-way interaction between the business firm and its customers. C2B commerce is a reality which provides the consumers with the freedom of shopping-at-will. Customers can also make use of call centres set up by companies to make queries and lodge complaints round the clock at no extra cost.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f54d8e6ddb2deb7d72' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'business-to-consumer-b2c-commerce-a-one-way-traffic' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f54d8e6ddb2deb7d72-en-9","language":"English","title":"Intra-B Commerce","topic_slug":"intra-b-commerce","definition":"Intra-B commerce refers to the interactions between parties involved in the electronic transactions from within a given business firm. Intra-B commerce is a critical component of e-business and enables a firm to reap advantages of efficient inventory and cash management, greater utilisation of plant and machinery, effective handling of customers'' orders, and effective human resource management.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f54d8e6ddb2deb7d72' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'intra-b-commerce' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f54d8e6ddb2deb7d74-en-10","language":"English","title":"Formation of a Company","topic_slug":"formation-of-a-company","definition":"A company is formed through a complex process involving various stages, including promotion, incorporation, and subscription. The company form of organization is preferred by many business firms due to its ability to raise funds from the public and its limited liability.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f54d8e6ddb2deb7d74' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'formation-of-a-company' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f54d8e6ddb2deb7d74-en-11","language":"English","title":"Functions of a Promoter","topic_slug":"functions-of-a-promoter","definition":"A promoter is a person who undertakes to form a company with reference to a given project and to set it going. The functions of a promoter include: Identification of business opportunity Feasibility studies Name approval Preparation of necessary documents Appointment of professionals","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f54d8e6ddb2deb7d74' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'functions-of-a-promoter' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f54d8e6ddb2deb7d74-en-12","language":"English","title":"Name Approval","topic_slug":"name-approval","definition":"A name is considered undesirable if it is identical with or too closely resembles the name of an existing company. A name is also considered undesirable if it is misleading or violative of the provisions of ''The Emblem and Names (Prevention of Improper Use) Act 1950''.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f54d8e6ddb2deb7d74' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'name-approval' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f54d8e6ddb2deb7d74-en-13","language":"English","title":"Preparation of Necessary Documents","topic_slug":"preparation-of-necessary-documents","definition":"The promoters have to prepare certain legal documents, which have to be submitted to the Registrar of Companies for getting the company registered. The documents required to be submitted include Memorandum of Association, Articles of Association, and Consent of Directors.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f54d8e6ddb2deb7d74' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'preparation-of-necessary-documents' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f54d8e6ddb2deb7d74-as-14","language":"Assamese","title":"কোম্পানীৰ প্ৰৱৰ্ত্তন","topic_slug":"কোম্পানীৰ-প্ৰৱৰ্ত্তন","definition":"প্ৰৱৰ্তন কোম্পানী গঠনৰ প্রথম পৰ্যায়। ইয়াত সাঙোৰ খাই আছে এটা ব্যৱসায়ৰ সুযোগৰ ধাৰণা লোৱা আৰু কোম্পানী গঠনৰ বাবে আগভাগ লোৱা। ‘প্ৰৱৰ্তন’ৰ অৰ্থ হ’ল কোনো এটা ব্যৱসায়িক সুযোগক বাস্তৱৰূপ দিয়া যাতে ব্যৱসায়টো আৰম্ভ কৰিব পৰা যায়। গতিকে কোম্পানীৰ গঠন আৰম্ভ হয় কোনো এজনৰ সম্ভাৱনীয় ব্যৱসায়ৰ সুযোগ সন্ধানৰ দ্বাৰা। এজন ব্যক্তি অথবা এদল ব্যক্তিয়ে অথবা কোনো কোম্পানীয়েও ব্যৱসায়ৰ সুযোগৰ সন্ধান পাব পাৰে। যদি কোনো ব্যক্তি বা এদল ব্যক্তিয়ে অথবা কোম্পানীয়ে ব্যৱসায় গঠনৰ বাবে ব্যৱসায়িক সুযোগ চিহ্নিত কৰে, তেতিয়া তেওঁলোকক প্ৰৱৰ্ত্তক বুলি কোৱা হয়। প্ৰৱৰ্ত্তকৰ কোনো বিধিবদ্ধ সংজ্ঞা নাই। প্ৰৱৰ্ত্তক তেওঁকেই কোৱা হয় যিজনে কোনো এটা প্রকল্পৰ/আঁচনিৰ সম্পৰ্কে কোম্পানীৰ গঠনৰ ভাৰ লয় আৰু যিয়ে উদ্দেশ্য সিদ্ধিৰ বাবে কোম্পানী গঠনৰ আৱশ্যকীয় ব্যৱস্থা গ্ৰহণ কৰে। প্ৰৱৰ্ত্তক কাৰ্য্যাৱলী: ব্যৱসায়ৰ সুযোগ চিহ্নিত কৰা: প্ৰৱৰ্ত্তকৰ প্রথম আৰু মুখ্য কাম হল ব্যৱসায়ৰ সুযোগ চিহ্নিত কৰা। সম্ভাৱনীয়তা সম্পৰ্কৰ অধ্যয়ন: চিহ্নিত কিছুমান ব্যৱসায়ৰ সুযোগ প্ৰতিষ্ঠানৰ বাবে সম্ভৱপৰ নহবও পাৰে। সেইগতিকে প্ৰৱৰ্ত্তকে সম্ভাৱনীয় সকলো দিশৰ অনুসন্ধান পুংখানুপুংখভাবে অধ্যয়ন কৰিব লাগিব।","title_as":"কোম্পানীৰ প্ৰৱৰ্ত্তন","topic_slug_as":"কোম্পানীৰ-প্ৰৱৰ্ত্তন","definition_as":"প্ৰৱৰ্তন কোম্পানী গঠনৰ প্রথম পৰ্যায়। ইয়াত সাঙোৰ খাই আছে এটা ব্যৱসায়ৰ সুযোগৰ ধাৰণা লোৱা আৰু কোম্পানী গঠনৰ বাবে আগভাগ লোৱা। ‘প্ৰৱৰ্তন’ৰ অৰ্থ হ’ল কোনো এটা ব্যৱসায়িক সুযোগক বাস্তৱৰূপ দিয়া যাতে ব্যৱসায়টো আৰম্ভ কৰিব পৰা যায়। গতিকে কোম্পানীৰ গঠন আৰম্ভ হয় কোনো এজনৰ সম্ভাৱনীয় ব্যৱসায়ৰ সুযোগ সন্ধানৰ দ্বাৰা। এজন ব্যক্তি অথবা এদল ব্যক্তিয়ে অথবা কোনো কোম্পানীয়েও ব্যৱসায়ৰ সুযোগৰ সন্ধান পাব পাৰে। যদি কোনো ব্যক্তি বা এদল ব্যক্তিয়ে অথবা কোম্পানীয়ে ব্যৱসায় গঠনৰ বাবে ব্যৱসায়িক সুযোগ চিহ্নিত কৰে, তেতিয়া তেওঁলোকক প্ৰৱৰ্ত্তক বুলি কোৱা হয়। প্ৰৱৰ্ত্তকৰ কোনো বিধিবদ্ধ সংজ্ঞা নাই। প্ৰৱৰ্ত্তক তেওঁকেই কোৱা হয় যিজনে কোনো এটা প্রকল্পৰ/আঁচনিৰ সম্পৰ্কে কোম্পানীৰ গঠনৰ ভাৰ লয় আৰু যিয়ে উদ্দেশ্য সিদ্ধিৰ বাবে কোম্পানী গঠনৰ আৱশ্যকীয় ব্যৱস্থা গ্ৰহণ কৰে। প্ৰৱৰ্ত্তক কাৰ্য্যাৱলী: ব্যৱসায়ৰ সুযোগ চিহ্নিত কৰা: প্ৰৱৰ্ত্তকৰ প্রথম আৰু মুখ্য কাম হল ব্যৱসায়ৰ সুযোগ চিহ্নিত কৰা। সম্ভাৱনীয়তা সম্পৰ্কৰ অধ্যয়ন: চিহ্নিত কিছুমান ব্যৱসায়ৰ সুযোগ প্ৰতিষ্ঠানৰ বাবে সম্ভৱপৰ নহবও পাৰে। সেইগতিকে প্ৰৱৰ্ত্তকে সম্ভাৱনীয় সকলো দিশৰ অনুসন্ধান পুংখানুপুংখভাবে অধ্যয়ন কৰিব লাগিব।","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f54d8e6ddb2deb7d74' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'কোম্পানীৰ-প্ৰৱৰ্ত্তন' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'Assamese');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f54d8e6ddb2deb7d74-as-15","language":"Assamese","title":"কোম্পানীৰ নিবন্ধন","topic_slug":"কোম্পানীৰ-নিবন্ধন","definition":"পঞ্জীয়কৰ ওচৰত আবেদন কৰিবলৈকে কোম্পানীৰ নিবন্ধন বুলি কোৱা হয়। এই ধাপে কোম্পানীৰ আইনৰ অধীনত কোম্পানীটোৰ অস্তিত্ব আৰম্ভ হয়। পঞ্জীয়নৰ বাবে আৱশ্যকীয় নথিপত্ৰসমূহ: স্মাৰকলিপি (Memorandum of Association) আৱ্যন্তৰীণ নিয়মাবলী (Articles of Association) সঞ্চালকসকলৰ সন্মতি পত্ৰ (Consent of Directors) অংশধাৰকসকলৰ নাম, ঠিকনা আৰু অংশপত্ৰৰ সংখ্যাৰ তালিকা (Return of Allotment)","title_as":"কোম্পানীৰ নিবন্ধন","topic_slug_as":"কোম্পানীৰ-নিবন্ধন","definition_as":"পঞ্জীয়কৰ ওচৰত আবেদন কৰিবলৈকে কোম্পানীৰ নিবন্ধন বুলি কোৱা হয়। এই ধাপে কোম্পানীৰ আইনৰ অধীনত কোম্পানীটোৰ অস্তিত্ব আৰম্ভ হয়। পঞ্জীয়নৰ বাবে আৱশ্যকীয় নথিপত্ৰসমূহ: স্মাৰকলিপি (Memorandum of Association) আৱ্যন্তৰীণ নিয়মাবলী (Articles of Association) সঞ্চালকসকলৰ সন্মতি পত্ৰ (Consent of Directors) অংশধাৰকসকলৰ নাম, ঠিকনা আৰু অংশপত্ৰৰ সংখ্যাৰ তালিকা (Return of Allotment)","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f54d8e6ddb2deb7d74' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'কোম্পানীৰ-নিবন্ধন' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'Assamese');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f44d8e6ddb2deb7d6f-en-16","language":"English","title":"Forms of Business Organisation","topic_slug":"forms-of-business-organisation","definition":"Business organisation refers to the structure and form in which a business is established and operated, including sole proprietorship, partnership, joint Hindu family business, joint stock companies, and co-operative societies. The choice of business organisation depends on factors like liability, control, capital, and legal formalities. Each form of business organisation has distinct features, advantages, and disadvantages that influence its suitability for different types of ventures.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f44d8e6ddb2deb7d6f' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'forms-of-business-organisation' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f44d8e6ddb2deb7d6f-en-17","language":"English","title":"Sole Proprietorship","topic_slug":"sole-proprietorship","definition":"A sole proprietorship is a business owned and managed by a single individual who has unlimited liability for the debts and obligations of the business. The owner has complete control over all decisions and enjoys all the profits, but also bears all the risks and losses. It is the simplest and most common form of business organisation, requiring minimal legal formalities for establishment and closure. The owner is personally liable for the business''s debts, meaning their personal assets can be used to settle business liabilities. This form is ideal for small-scale businesses with limited capital and operations, such as retail shops, service providers, and local enterprises.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f44d8e6ddb2deb7d6f' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'sole-proprietorship' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f44d8e6ddb2deb7d6f-en-18","language":"English","title":"Hindu Undivided Family Business","topic_slug":"hindu-undivided-family-business","definition":"A Hindu Undivided Family (HUF) business is a traditional form of organisation where the business is managed by the members of a joint Hindu family. The business is controlled by the Karta, usually the eldest male member, who makes decisions for the family and the business. All family members have a right to share in the profits, but the Karta has the ultimate authority over business operations. The liability of the family members is limited to their share in the business, and their personal assets are not at risk. The 2008 amendment to the Hindu Succession Act granted daughters equal rights in ancestral property, promoting gender equality in this form of organisation.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f44d8e6ddb2deb7d6f' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'hindu-undivided-family-business' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f44d8e6ddb2deb7d6f-en-19","language":"English","title":"Partnership","topic_slug":"partnership","definition":"A partnership is a business organisation where two or more individuals agree to share the profits and losses of a business, with a mutual agency relationship. Partnerships can be general or limited, depending on the level of liability and involvement of each partner. The Partnership Act, 1932 governs the legal framework of partnerships in India, outlining rights, duties, and responsibilities of partners. Partners share the profits, bear the risks, and have joint and several liability for the business''s debts. This form is suitable for businesses requiring more capital and expertise than a sole proprietorship, such as professional services, retail, and small-scale industries.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f44d8e6ddb2deb7d6f' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'partnership' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f44d8e6ddb2deb7d6f-en-20","language":"English","title":"Joint Stock Company","topic_slug":"joint-stock-company","definition":"A joint stock company is a business organisation where ownership is divided into shares, and shareholders have limited liability. It is a separate legal entity, distinct from its owners, and can own property, enter contracts, and sue or be sued in its own name. Companies can be private or public, with public companies requiring more regulatory compliance and transparency. Shareholders elect a board of directors to manage the company, and profits are distributed as dividends. This form is ideal for large-scale businesses needing substantial capital, such as manufacturing, banking, and technology sectors.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f44d8e6ddb2deb7d6f' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'joint-stock-company' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f44d8e6ddb2deb7d6f-en-21","language":"English","title":"Co-operative Society","topic_slug":"co-operative-society","definition":"A co-operative society is a voluntary association of individuals who come together to achieve a common economic goal, such as providing services or goods at fair prices. It operates on the principles of self-help, mutual aid, and democratic control, with each member having an equal vote regardless of their shareholding. Co-operatives are registered under the Co-operative Societies Act and are governed by a board of directors elected by members. Profits are distributed among members based on their participation in the society, rather than their capital contribution. This form promotes social equity and community development, often seen in agriculture, housing, and consumer services.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f44d8e6ddb2deb7d6f' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'co-operative-society' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f44d8e6ddb2deb7d6f-as-22","language":"Assamese","title":"ব্যৱসায় সংগঠনৰ প্ৰকাৰসমূহ","topic_slug":"ব্যৱসায়-সংগঠনৰ-প্ৰকাৰসমূহ","definition":"শিকাৰ উদ্দেশ্য: এই অধ্যায়টি অধ্যয়ন কৰি আমি জানিবলৈ সক্ষম হ’ম— ব্যৱসায় সংগঠনৰ বিভিন্ন প্ৰকাৰসমূহ চিনাক্ত কৰিবলৈ; বাছনি কৰা ব্যৱসায় সংগঠনৰ বৈশিষ্ট্য, সুবিধা-অসুবিধা সমুহ ব্যাখ্যা কৰিবলৈ; বিভিন্ন ব্যৱসায় সংগঠনসমূহৰ মাজত থকা পাৰ্থক্য দেখুৱাবলৈ আৰু উপযুক্ত ব্যৱসায় সংগঠন বাছনিৰ কাৰকসমূহ বিশ্লেষণ কৰিবলৈ। নেহা এজনী উচ্চতৰ মাধ্যমিকৰ মেধাবী ছাত্ৰী। পৰীক্ষা দি ফলাফল ঘোষণাৰ বাবে অপক্ষা কৰি আছে। ঘৰত থকা আজৰি সময়খিনি ব্যৱহাৰ কৰিবৰ বাবে সিদ্ধান্ত লৈছে। তেওঁৰ চিত্ৰ অঙ্কনৰ প্ৰতি ৰাপ আছে আৰু সেইবাবে তেওঁ মৎশিল্প, ফুলদানি, চৰিয়া আদি নানান সামগ্ৰী তৈয়াৰ কৰি বিভিন্ন ৰঙেৰে কাৰুকাৰ্য্যৰে দেখনিয়াৰ কৰি অঙ্কন কৰিবলৈ ইচ্ছা কৰিছে। তেওঁৰ এই কামৰ বাবে ওচৰ-চুবুৰীয়া, বন্ধু-বান্ধৱে প্ৰশংসা কৰাৰ বাবে উৎসাহিত হয়। তেওঁৰ এই ৰংচঙীয়া মাটিৰ সামগ্ৰী কিছুসংখ্যক কলনীত বাস কৰা বাসিন্দাসকলৰ ওচৰত বিক্ৰী কৰে। নিজৰ ঘৰৰ পৰা আৰম্ভ কৰা এই ব্যৱসায় ওচৰৰ ভাড়া ঘৰলৈ লৈ যায়। তেওঁৰ ব্যক্তিগত মালিকীস্বত্বৰ ব্যৱসায়ৰ প্ৰসাৰ হোৱাৰ লগে লগে যথেষ্ট জনপ্ৰিয়তা অৰ্জন কৰে।","title_as":"ব্যৱসায় সংগঠনৰ প্ৰকাৰসমূহ","topic_slug_as":"ব্যৱসায়-সংগঠনৰ-প্ৰকাৰসমূহ","definition_as":"শিকাৰ উদ্দেশ্য: এই অধ্যায়টি অধ্যয়ন কৰি আমি জানিবলৈ সক্ষম হ’ম— ব্যৱসায় সংগঠনৰ বিভিন্ন প্ৰকাৰসমূহ চিনাক্ত কৰিবলৈ; বাছনি কৰা ব্যৱসায় সংগঠনৰ বৈশিষ্ট্য, সুবিধা-অসুবিধা সমুহ ব্যাখ্যা কৰিবলৈ; বিভিন্ন ব্যৱসায় সংগঠনসমূহৰ মাজত থকা পাৰ্থক্য দেখুৱাবলৈ আৰু উপযুক্ত ব্যৱসায় সংগঠন বাছনিৰ কাৰকসমূহ বিশ্লেষণ কৰিবলৈ। নেহা এজনী উচ্চতৰ মাধ্যমিকৰ মেধাবী ছাত্ৰী। পৰীক্ষা দি ফলাফল ঘোষণাৰ বাবে অপক্ষা কৰি আছে। ঘৰত থকা আজৰি সময়খিনি ব্যৱহাৰ কৰিবৰ বাবে সিদ্ধান্ত লৈছে। তেওঁৰ চিত্ৰ অঙ্কনৰ প্ৰতি ৰাপ আছে আৰু সেইবাবে তেওঁ মৎশিল্প, ফুলদানি, চৰিয়া আদি নানান সামগ্ৰী তৈয়াৰ কৰি বিভিন্ন ৰঙেৰে কাৰুকাৰ্য্যৰে দেখনিয়াৰ কৰি অঙ্কন কৰিবলৈ ইচ্ছা কৰিছে। তেওঁৰ এই কামৰ বাবে ওচৰ-চুবুৰীয়া, বন্ধু-বান্ধৱে প্ৰশংসা কৰাৰ বাবে উৎসাহিত হয়। তেওঁৰ এই ৰংচঙীয়া মাটিৰ সামগ্ৰী কিছুসংখ্যক কলনীত বাস কৰা বাসিন্দাসকলৰ ওচৰত বিক্ৰী কৰে। নিজৰ ঘৰৰ পৰা আৰম্ভ কৰা এই ব্যৱসায় ওচৰৰ ভাড়া ঘৰলৈ লৈ যায়। তেওঁৰ ব্যক্তিগত মালিকীস্বত্বৰ ব্যৱসায়ৰ প্ৰসাৰ হোৱাৰ লগে লগে যথেষ্ট জনপ্ৰিয়তা অৰ্জন কৰে।","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f44d8e6ddb2deb7d6f' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'ব্যৱসায়-সংগঠনৰ-প্ৰকাৰসমূহ' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'Assamese');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f64d8e6ddb2deb7d77-en-23","language":"English","title":"Meaning and Types of Internal Trade","topic_slug":"meaning-and-types-of-internal-trade","definition":"Internal trade refers to the buying and selling of goods and services within the boundaries of a nation. It is the exchange of goods and services between individuals or establishments within a country. Internal trade can be classified into two broad categories: (i) wholesale trade and (ii) retail trade.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f64d8e6ddb2deb7d77' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'meaning-and-types-of-internal-trade' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f64d8e6ddb2deb7d77-en-24","language":"English","title":"Importance of Internal Trade","topic_slug":"importance-of-internal-trade","definition":"Internal trade plays a vital role in the economic development of a country. It helps in the equitable distribution of goods and services within a nation. It promotes economic growth and development by creating employment opportunities and increasing the standard of living.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f64d8e6ddb2deb7d77' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'importance-of-internal-trade' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f64d8e6ddb2deb7d77-en-25","language":"English","title":"Types of Internal Trade","topic_slug":"types-of-internal-trade","definition":"Internal trade can be classified into two broad categories: (i) wholesale trade and (ii) retail trade. Wholesale trade refers to the buying and selling of goods and services in large quantities for the purpose of resale or intermediate use. Retail trade refers to the purchase and sale of goods and services in relatively small quantities to the ultimate consumers.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f64d8e6ddb2deb7d77' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'types-of-internal-trade' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f64d8e6ddb2deb7d77-en-26","language":"English","title":"Services of Wholesalers to Manufacturers","topic_slug":"services-of-wholesalers-to-manufacturers","definition":"Facilitating large scale production: Wholesalers collect small orders from a number of retailers and pass on the pool of such orders to the manufacturers, enabling them to undertake production on a large scale and take advantage of the economies of scale. Bearing risk: Wholesalers deal in goods in their own name, take delivery of the goods, and keep the goods purchased in large lots in their warehouses, bearing various risks such as the risk of fall in prices, theft, pilferage, spoilage, fire, etc. Financial assistance: Wholesalers provide financial assistance to the manufacturers by making cash payment for the goods purchased by them. Facilitating production continuity: Wholesalers facilitate continuity of production activity throughout the year by purchasing the goods as and when these are produced and storing them till the time these are demanded by retailers or consumers in the market.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f64d8e6ddb2deb7d77' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'services-of-wholesalers-to-manufacturers' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f64d8e6ddb2deb7d77-en-27","language":"English","title":"Services of Wholesalers to Retailers","topic_slug":"services-of-wholesalers-to-retailers","definition":"Availability of goods: Wholesalers make the products of various manufacturers readily available to the retailers, relieving them of the work of collecting goods from several producers and keeping big inventory of the same. Marketing support: Wholesalers perform various marketing functions and provide support to the retailers, undertaking advertising and other sales promotional activities to induce customers to purchase the goods. Grant of credit: Wholesalers generally extend credit facilities to their regular customers, enabling the retailers to manage their business with relatively small amount of working capital. Specialised knowledge: Wholesalers specialise in one line of products and know the pulse of the market, passing on the benefit of their specialised knowledge to the retailers.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f64d8e6ddb2deb7d77' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'services-of-wholesalers-to-retailers' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f64d8e6ddb2deb7d77-en-28","language":"English","title":"Retail Trade","topic_slug":"retail-trade","definition":"A retailer is a business enterprise that is engaged in the sale of goods and services directly to the ultimate consumers. Retailers normally buy goods in large quantities from the wholesalers and sell them in small quantities to the ultimate consumers. Retailing is that branch of business which is devoted to the sale of goods and services to the ultimate consumers for their personal and non-business use. There may be different ways of selling the goods, viz., personally, on telephone, or through vending machines. The products may be sold at different places, viz., in a store, at the customer’s house, or any other place.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f64d8e6ddb2deb7d77' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'retail-trade' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f64d8e6ddb2deb7d77-as-29","language":"Assamese","title":"উৎপাদনকাৰী আৰু খুচুৰা বিক্ৰেতাৰ প্রতি পাইকাৰী বিক্ৰেতা সকলৰ সেৱাবোৰ","topic_slug":"উৎপাদনকাৰী-আৰু-খুচুৰা-বিক্ৰেতাৰ-প্রতি-পাইকাৰী-বিক্ৰেতা-সকলৰ-সেৱাবোৰ","definition":"পাইকাৰী বিক্ৰেতাসকলে উৎপাদনকাৰী আৰু খুচুৰা বিক্ৰেতা উভয়কে বিভিন্ন সেৱা আগবঢ়ায়। ইয়াৰ ভিতৰত অন্যতম হ’ল: বৃহৎ উৎপাদনৰ সুচলতা: পাইকাৰী বিক্ৰেতাসকলে বৃহৎ পৰিমাণে পণ্য ক্ৰয় কৰি উৎপাদনকাৰীক বৃহৎ উৎপাদনলৈ উৎসাহিত কৰে। বিপদ বহন: পাইকাৰী বিক্ৰেতাসকলে সামগ্ৰী মজুত কৰাৰ বিপদ (মূল্যৰ উঠানামা, চুৰি, ক্ষতি) নিজে লোৱাৰ ফলত উৎপাদনকাৰীসকলে দুশ্চিন্তামুক্ত থাকে। বিত্তীয় সাহায্য: পাইকাৰী বিক্ৰেতাসকলে উৎপাদনকাৰীক অগ্ৰিম ধন দি সহায় কৰে। অভিজ্ঞ পৰামৰ্শ: বজাৰৰ তথ্য আৰু গ্ৰাহকৰ পছন্দৰ বিষয়ে মূল্যবান পৰামৰ্শ দিয়ে। বিপণনৰ সহায়: বিজ্ঞাপন আৰু অন্যান্য বিপণন কাৰ্য্যৰ মাধ্যমেৰে সহায় কৰে। মজুতকৰণ: সামগ্ৰী মজুত কৰি ৰাখে আৰু চাহিদা অনুযায়ী যোগান ধৰে।","title_as":"উৎপাদনকাৰী আৰু খুচুৰা বিক্ৰেতাৰ প্রতি পাইকাৰী বিক্ৰেতা সকলৰ সেৱাবোৰ","topic_slug_as":"উৎপাদনকাৰী-আৰু-খুচুৰা-বিক্ৰেতাৰ-প্রতি-পাইকাৰী-বিক্ৰেতা-সকলৰ-সেৱাবোৰ","definition_as":"পাইকাৰী বিক্ৰেতাসকলে উৎপাদনকাৰী আৰু খুচুৰা বিক্ৰেতা উভয়কে বিভিন্ন সেৱা আগবঢ়ায়। ইয়াৰ ভিতৰত অন্যতম হ’ল: বৃহৎ উৎপাদনৰ সুচলতা: পাইকাৰী বিক্ৰেতাসকলে বৃহৎ পৰিমাণে পণ্য ক্ৰয় কৰি উৎপাদনকাৰীক বৃহৎ উৎপাদনলৈ উৎসাহিত কৰে। বিপদ বহন: পাইকাৰী বিক্ৰেতাসকলে সামগ্ৰী মজুত কৰাৰ বিপদ (মূল্যৰ উঠানামা, চুৰি, ক্ষতি) নিজে লোৱাৰ ফলত উৎপাদনকাৰীসকলে দুশ্চিন্তামুক্ত থাকে। বিত্তীয় সাহায্য: পাইকাৰী বিক্ৰেতাসকলে উৎপাদনকাৰীক অগ্ৰিম ধন দি সহায় কৰে। অভিজ্ঞ পৰামৰ্শ: বজাৰৰ তথ্য আৰু গ্ৰাহকৰ পছন্দৰ বিষয়ে মূল্যবান পৰামৰ্শ দিয়ে। বিপণনৰ সহায়: বিজ্ঞাপন আৰু অন্যান্য বিপণন কাৰ্য্যৰ মাধ্যমেৰে সহায় কৰে। মজুতকৰণ: সামগ্ৰী মজুত কৰি ৰাখে আৰু চাহিদা অনুযায়ী যোগান ধৰে।","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f64d8e6ddb2deb7d77' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'উৎপাদনকাৰী-আৰু-খুচুৰা-বিক্ৰেতাৰ-প্রতি-পাইকাৰী-বিক্ৰেতা-সকলৰ-সেৱাবোৰ' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'Assamese');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f64d8e6ddb2deb7d77-as-30","language":"Assamese","title":"খুচুৰা বিক্ৰেতাসকলৰ সেৱাবোৰ","topic_slug":"খুচুৰা-বিক্ৰেতাসকলৰ-সেৱাবোৰ","definition":"খুচুৰা বিক্ৰেতাসকলে সৰ্বশেষ গ্ৰাহকলৈ সামগ্ৰী আৰু সেৱা প্ৰদান কৰে। তেওঁলোকৰ সেৱাসমূহ হ’ল: পণ্যৰ পৰ্যাপ্ততা: বিভিন্ন ধৰণৰ সামগ্ৰী সহজলভ্য কৰে। বিপণনৰ সুবিধা: বিজ্ঞাপনৰ মাধ্যমেৰে গ্ৰাহকক আকৰ্ষণ কৰে। বাকী প্ৰদান: কিছু ক্ষেত্ৰত গ্ৰাহকলৈ বাকীৰ সুবিধা দিয়ে। বিশেষ জ্ঞান: সামগ্ৰীৰ বিষয়ে সঠিক তথ্য আৰু পৰামৰ্শ দিয়ে। বিপদ ভাগকৰণ: পাইকাৰী বিক্ৰেতাসকলৰ পৰা কম পৰিমাণে ক্ৰয় কৰাৰ বাবে বিপদ কম হয়।","title_as":"খুচুৰা বিক্ৰেতাসকলৰ সেৱাবোৰ","topic_slug_as":"খুচুৰা-বিক্ৰেতাসকলৰ-সেৱাবোৰ","definition_as":"খুচুৰা বিক্ৰেতাসকলে সৰ্বশেষ গ্ৰাহকলৈ সামগ্ৰী আৰু সেৱা প্ৰদান কৰে। তেওঁলোকৰ সেৱাসমূহ হ’ল: পণ্যৰ পৰ্যাপ্ততা: বিভিন্ন ধৰণৰ সামগ্ৰী সহজলভ্য কৰে। বিপণনৰ সুবিধা: বিজ্ঞাপনৰ মাধ্যমেৰে গ্ৰাহকক আকৰ্ষণ কৰে। বাকী প্ৰদান: কিছু ক্ষেত্ৰত গ্ৰাহকলৈ বাকীৰ সুবিধা দিয়ে। বিশেষ জ্ঞান: সামগ্ৰীৰ বিষয়ে সঠিক তথ্য আৰু পৰামৰ্শ দিয়ে। বিপদ ভাগকৰণ: পাইকাৰী বিক্ৰেতাসকলৰ পৰা কম পৰিমাণে ক্ৰয় কৰাৰ বাবে বিপদ কম হয়।","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f64d8e6ddb2deb7d77' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'খুচুৰা-বিক্ৰেতাসকলৰ-সেৱাবোৰ' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'Assamese');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f64d8e6ddb2deb7d77-as-31","language":"Assamese","title":"ক্ষুদ্ৰ আৰু বৃহৎ আকাৰৰ খুচুৰা বিক্ৰেতাৰ ভিন্‌ ভিন্‌ ৰূপবোৰ","topic_slug":"ক্ষুদ্ৰ-আৰু-বৃহৎ-আকাৰৰ-খুচুৰা-বিক্ৰেতাৰ-ভিন্-ভিন্-ৰূপবোৰ","definition":"ক্ষুদ্ৰ বিক্ৰেতা: এইসকলে সৰু দোকান বা ঘৰৰ পৰা বেপাৰ কৰে। ইয়াৰ মূলধন কম আৰু স্থানীয় গ্ৰাহকৰ ওপৰত নিৰ্ভৰশীল। বৃহৎ বিক্ৰেতা: এইসকলে বৃহৎ দোকান বা চেইন শ্বপৰ মাধ্যমেৰে বেপাৰ কৰে। ইয়াৰ মূলধন বেছি আৰু বহুতো গ্ৰাহকৰ সুবিধাৰ বাবে বিভিন্ন ঠাইত শাখা থাকে।","title_as":"ক্ষুদ্ৰ আৰু বৃহৎ আকাৰৰ খুচুৰা বিক্ৰেতাৰ ভিন্‌ ভিন্‌ ৰূপবোৰ","topic_slug_as":"ক্ষুদ্ৰ-আৰু-বৃহৎ-আকাৰৰ-খুচুৰা-বিক্ৰেতাৰ-ভিন্-ভিন্-ৰূপবোৰ","definition_as":"ক্ষুদ্ৰ বিক্ৰেতা: এইসকলে সৰু দোকান বা ঘৰৰ পৰা বেপাৰ কৰে। ইয়াৰ মূলধন কম আৰু স্থানীয় গ্ৰাহকৰ ওপৰত নিৰ্ভৰশীল। বৃহৎ বিক্ৰেতা: এইসকলে বৃহৎ দোকান বা চেইন শ্বপৰ মাধ্যমেৰে বেপাৰ কৰে। ইয়াৰ মূলধন বেছি আৰু বহুতো গ্ৰাহকৰ সুবিধাৰ বাবে বিভিন্ন ঠাইত শাখা থাকে।","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f64d8e6ddb2deb7d77' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'ক্ষুদ্ৰ-আৰু-বৃহৎ-আকাৰৰ-খুচুৰা-বিক্ৰেতাৰ-ভিন্-ভিন্-ৰূপবোৰ' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'Assamese');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f64d8e6ddb2deb7d77-as-32","language":"Assamese","title":"সামগ্ৰী আৰু সেৱা কৰ (GST) ধাৰণা আৰু প্রধান বৈশিষ্ট্য","topic_slug":"সামগ্ৰী-আৰু-সেৱা-কৰ-gst-ধাৰণা-আৰু-প্রধান-বৈশিষ্ট্য","definition":"GST (Goods and Services Tax) হৈছে ভাৰতৰ এক পৰোক্ষ কৰ যি সামগ্ৰী আৰু সেৱাৰ ওপৰত আৰোপ কৰা হয়। ইয়াৰ মূল বৈশিষ্ট্যবোৰ হ’ল: একক কৰ: ইয়াৰ দ্বাৰা বিভিন্ন ধৰণৰ কৰ (Excise, VAT, Service Tax) অন্তৰ্ভুক্ত কৰা হৈছে। কৰৰ শৃঙ্খল: প্ৰতিটো স্তৰত কৰ যোগ হয়, কিন্তু চূড়ান্ত গ্ৰাহকৰ পৰাহে সংগৃহীত হয়। ইন্পুট ট्याক্স ক্রেডিট: ব্যৱসায়িকসকলে তেওঁলোকৰ কেনা সামগ্ৰীৰ কৰৰ পৰিমাণ পুনৰুদ্ধাৰ কৰিব পাৰে।","title_as":"সামগ্ৰী আৰু সেৱা কৰ (GST) ধাৰণা আৰু প্রধান বৈশিষ্ট্য","topic_slug_as":"সামগ্ৰী-আৰু-সেৱা-কৰ-gst-ধাৰণা-আৰু-প্রধান-বৈশিষ্ট্য","definition_as":"GST (Goods and Services Tax) হৈছে ভাৰতৰ এক পৰোক্ষ কৰ যি সামগ্ৰী আৰু সেৱাৰ ওপৰত আৰোপ কৰা হয়। ইয়াৰ মূল বৈশিষ্ট্যবোৰ হ’ল: একক কৰ: ইয়াৰ দ্বাৰা বিভিন্ন ধৰণৰ কৰ (Excise, VAT, Service Tax) অন্তৰ্ভুক্ত কৰা হৈছে। কৰৰ শৃঙ্খল: প্ৰতিটো স্তৰত কৰ যোগ হয়, কিন্তু চূড়ান্ত গ্ৰাহকৰ পৰাহে সংগৃহীত হয়। ইন্পুট ট्याক্স ক্রেডিট: ব্যৱসায়িকসকলে তেওঁলোকৰ কেনা সামগ্ৰীৰ কৰৰ পৰিমাণ পুনৰুদ্ধাৰ কৰিব পাৰে।","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f64d8e6ddb2deb7d77' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'সামগ্ৰী-আৰু-সেৱা-কৰ-gst-ধাৰণা-আৰু-প্রধান-বৈশিষ্ট্য' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'Assamese');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a25e929473568d758063f8f-en-33","language":"English","title":"Meaning of International Business","topic_slug":"meaning-of-international-business","definition":"International business refers to business transactions that take place across the national frontiers. It involves not only the international movement of goods and services but also of capital, personnel, technology, and intellectual property like patents, trademarks, know-how, and copyrights. International business is a broader term and is comprised of both the trade and production of goods and services across frontiers.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a25e929473568d758063f8f' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'meaning-of-international-business' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a25e929473568d758063f8f-en-34","language":"English","title":"Reason for International Business","topic_slug":"reason-for-international-business","definition":"The fundamental reason behind international business is that countries cannot produce equally well or cheaply all that they need. This is due to the unequal distribution of natural resources among nations or differences in their productivity levels. Availability of various factors of production such as labour, capital, and raw materials that are required for producing different goods and services differ among nations. Labour productivity and production costs also differ among nations due to various socio-economic, geographical, and political reasons.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a25e929473568d758063f8f' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'reason-for-international-business' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a25e929473568d758063f8f-en-35","language":"English","title":"International Business vs. Domestic Business","topic_slug":"international-business-vs-domestic-business","definition":"Conducting and managing international business operations is more complex than undertaking domestic business. This is because of variations in political, social, cultural, and economic environments of countries. Business firms find it difficult to extend their domestic business strategy to foreign markets. To be successful in the overseas markets, they need to adapt their product, pricing, promotion, and distribution strategies and overall business plans to suit the specific requirements of the target foreign markets.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a25e929473568d758063f8f' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'international-business-vs-domestic-business' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a25e929473568d758063f8f-en-36","language":"English","title":"Benefits of International Business","topic_slug":"benefits-of-international-business","definition":"Nations and firms derive several benefits from international business, including: Price considerations: Firms import what is available at lower prices in other countries and export goods to other countries where they can fetch better prices for their products. Increased opportunities for growth and profits: International business presents numerous opportunities for growth and increased profits. Access to new markets: International business provides access to new markets and customers. Diversification of risks: By engaging in international business, firms can diversify their risks and reduce their dependence on a single market or customer.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a25e929473568d758063f8f' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'benefits-of-international-business' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a25e929473568d758063f8f-en-37","language":"English","title":"Scope of International Business","topic_slug":"scope-of-international-business","definition":"The scope of international business has substantially expanded in recent years. International trade in services such as international travel and tourism, transportation, communication, banking, warehousing, distribution, and advertising has considerably grown. Increased foreign investments and overseas production of goods and services have also become important developments in international business.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a25e929473568d758063f8f' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'scope-of-international-business' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a25e929473568d758063f8f-en-38","language":"English","title":"Types of International Business","topic_slug":"types-of-international-business","definition":"There are several types of international business, including: Export business: This involves the sale of goods or services by a firm in one country to customers in another country. Import business: This involves the purchase of goods or services by a firm in one country from suppliers in another country. Joint venture: This involves a partnership between two or more firms from different countries to undertake a specific business activity. Licensing: This involves the granting of permission by a firm in one country to a firm in another country to use its technology, patents, or trademarks.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a25e929473568d758063f8f' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'types-of-international-business' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a25e929473568d758063f8f-en-39","language":"English","title":"Documents Required for Import and Export Transactions","topic_slug":"documents-required-for-import-and-export-transactions","definition":"The following documents are required for import and export transactions: Bill of lading: This is a document that serves as evidence of the shipment of goods. Commercial invoice: This is a document that provides details of the goods being exported or imported. Packing list: This is a document that provides details of the goods being packed and shipped. Certificate of origin: This is a document that provides details of the country of origin of the goods being exported.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a25e929473568d758063f8f' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'documents-required-for-import-and-export-transactions' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a25e929473568d758063f8f-en-40","language":"English","title":"Incentives and Schemes Available for International Firms","topic_slug":"incentives-and-schemes-available-for-international-firms","definition":"There are several incentives and schemes available for international firms, including: Tax incentives: Many countries offer tax incentives to international firms to encourage them to set up operations in their country. Subsidies: Some countries offer subsidies to international firms to help them establish themselves in the market. Investment incentives: Many countries offer investment incentives to international firms to encourage them to invest in their country.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a25e929473568d758063f8f' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'incentives-and-schemes-available-for-international-firms' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a25e929473568d758063f8f-en-41","language":"English","title":"Role of Different Organisations for the Promotion of International Business","topic_slug":"role-of-different-organisations-for-the-promotion-of-international-business","definition":"There are several organisations that play a key role in promoting international business, including: World Trade Organisation (WTO): The WTO is an international organisation that promotes free trade and provides a forum for countries to negotiate trade agreements. International Chamber of Commerce (ICC): The ICC is a non-governmental organisation that promotes international trade and provides a forum for businesses to discuss trade issues. United Nations Conference on Trade and Development (UNCTAD): UNCTAD is a UN agency that promotes international trade and development.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a25e929473568d758063f8f' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'role-of-different-organisations-for-the-promotion-of-international-business' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a25e929473568d758063f8f-en-42","language":"English","title":"Major International Institutions and Agreements at the Global Level","topic_slug":"major-international-institutions-and-agreements-at-the-global-level","definition":"There are several major international institutions and agreements at the global level that promote international trade and development, including: General Agreement on Tariffs and Trade (GATT): GATT is a multilateral trade agreement that aims to reduce tariffs and other trade barriers. World Trade Organisation (WTO): The WTO is an international organisation that promotes free trade and provides a forum for countries to negotiate trade agreements. International Monetary Fund (IMF): The IMF is an international organisation that promotes international monetary cooperation and provides financial assistance to countries in need.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a25e929473568d758063f8f' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'major-international-institutions-and-agreements-at-the-global-level' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a25e929473568d758063f8f-as-43","language":"Assamese","title":"আন্তঃজাতীয় ব্যৱসায়ৰ অৰ্থ","topic_slug":"আন্তঃজাতীয়-ব্যৱসায়ৰ-অৰ্থ","definition":"এখন দেশৰ ভৌগোলিক চাৰিসীমাৰ ভিতৰত সংঘটিত হোৱা ব্যৱসায়িক লেনদেনক ঘৰুৱা বা ৰাষ্ট্ৰীয় ব্যৱসায় বুলি জনা যায়। আনহাতে, যিবোৰ ব্যৱসায়িক কাম-কাজ দেশৰ চাৰিসীমাৰ বাহিৰত সংঘটিত হয়, সেইবোৰক আন্তঃজাতীয় বা বহিঃব্যৱসায় হিচাপে আখ্যা দিয়া হয়। এই ব্যৱসায় কেৱল পণ্য আৰু সেৱাৰ আন্তঃজাতীয় চলাচলৰ সৈতেই নহয়, মূলধন, ব্যক্তি, প্রযুক্তিবিদ্যা আৰু বৌদ্ধিক সম্পত্তি (পেটেণ্ট, ট্ৰেডমাৰ্ক, কপিৰাইট) আদিৰ সৈতেও জড়িত।","title_as":"আন্তঃজাতীয় ব্যৱসায়ৰ অৰ্থ","topic_slug_as":"আন্তঃজাতীয়-ব্যৱসায়ৰ-অৰ্থ","definition_as":"এখন দেশৰ ভৌগোলিক চাৰিসীমাৰ ভিতৰত সংঘটিত হোৱা ব্যৱসায়িক লেনদেনক ঘৰুৱা বা ৰাষ্ট্ৰীয় ব্যৱসায় বুলি জনা যায়। আনহাতে, যিবোৰ ব্যৱসায়িক কাম-কাজ দেশৰ চাৰিসীমাৰ বাহিৰত সংঘটিত হয়, সেইবোৰক আন্তঃজাতীয় বা বহিঃব্যৱসায় হিচাপে আখ্যা দিয়া হয়। এই ব্যৱসায় কেৱল পণ্য আৰু সেৱাৰ আন্তঃজাতীয় চলাচলৰ সৈতেই নহয়, মূলধন, ব্যক্তি, প্রযুক্তিবিদ্যা আৰু বৌদ্ধিক সম্পত্তি (পেটেণ্ট, ট্ৰেডমাৰ্ক, কপিৰাইট) আদিৰ সৈতেও জড়িত।","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a25e929473568d758063f8f' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'আন্তঃজাতীয়-ব্যৱসায়ৰ-অৰ্থ' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'Assamese');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a25e929473568d758063f8f-as-44","language":"Assamese","title":"আন্তঃজাতীয় ব্যৱসায়ৰ কাৰণসমূহ","topic_slug":"আন্তঃজাতীয়-ব্যৱসায়ৰ-কাৰণসমূহ","definition":"আন্তঃজাতীয় ব্যৱসায়ৰ মূল কাৰণ হৈছে দেশসমূহে নিজৰ প্ৰয়োজনীয় সকলোখিনি সমান বা কম সময়ত উৎপাদন কৰিব নোৱাৰা। প্ৰাকৃতিক সম্পদৰ অসম বিতৰণ, উৎপাদনশীলতাৰ স্তৰৰ পাৰ্থক্য আদিৰ বাবে এনে হয়। বিভিন্ন দেশৰ আৰ্থ-সামাজিক, ভৌগোলিক আৰু ৰাজনৈতিক পৰিস্থিতিৰ বাবেও শ্রমিকৰ উৎপাদনশীলতা আৰু উৎপাদন ব্যয় বেলেগ হয়।","title_as":"আন্তঃজাতীয় ব্যৱসায়ৰ কাৰণসমূহ","topic_slug_as":"আন্তঃজাতীয়-ব্যৱসায়ৰ-কাৰণসমূহ","definition_as":"আন্তঃজাতীয় ব্যৱসায়ৰ মূল কাৰণ হৈছে দেশসমূহে নিজৰ প্ৰয়োজনীয় সকলোখিনি সমান বা কম সময়ত উৎপাদন কৰিব নোৱাৰা। প্ৰাকৃতিক সম্পদৰ অসম বিতৰণ, উৎপাদনশীলতাৰ স্তৰৰ পাৰ্থক্য আদিৰ বাবে এনে হয়। বিভিন্ন দেশৰ আৰ্থ-সামাজিক, ভৌগোলিক আৰু ৰাজনৈতিক পৰিস্থিতিৰ বাবেও শ্রমিকৰ উৎপাদনশীলতা আৰু উৎপাদন ব্যয় বেলেগ হয়।","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a25e929473568d758063f8f' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'আন্তঃজাতীয়-ব্যৱসায়ৰ-কাৰণসমূহ' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'Assamese');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a25e929473568d758063f8f-as-45","language":"Assamese","title":"আন্তঃজাতীয় ব্যৱসায় বনাম ঘৰুৱা ব্যৱসায়","topic_slug":"আন্তঃজাতীয়-ব্যৱসায়-বনাম-ঘৰুৱা-ব্যৱসায়","definition":"আন্তঃজাতীয় ব্যৱসায়িক কামকাজ পৰিচালনা কৰাটো ঘৰুৱা ব্যৱসায়তকৈ জটিল। দুয়োৰ মাজৰ কিছু পাৰ্থক্য তলত উল্লেখ কৰা হ’ল: ১. ক্ৰেতা আৰু বিক্ৰেতাৰ জাতীয়তা: আন্তঃজাতীয় ব্যৱসায়ত ক্ৰেতা আৰু বিক্ৰেতা বেলেগে বেলেগ দেশৰ হয়, যাৰ ফলত পাৰস্পৰিক বুজাবুজি কম হ’ব পাৰে। ২. অন্যান্য স্বাৰ্থজড়িত পক্ষৰ জাতীয়তা: ব্যৱসায়িক প্ৰতিষ্ঠানৰ সৈতে জড়িত কৰ্মচাৰী, যোগানভিটাৰ, আৰু অন্যান্য অংশীদাৰৰ জাতীয়তা ভিন্ন হোৱাৰ বাবে প্ৰমূল্যবোধ আৰু আচৰণত ভিন্নতা দেখা যায়। ৩. নিয়ম-কানুন: আন্তঃজাতীয় ব্যৱসায়ত বিভিন্ন দেশৰ নিয়ম-কানুন, সংস্কৃতি আৰু ব্যৱসায়িক প্ৰথাৰ ভিন্নতাৰ বাবে জটিলতা সৃষ্টি হ’ব পাৰে। ৪. মুদ্ৰা: বিভিন্ন দেশৰ মুদ্ৰাৰ বিনিময় হাৰৰ (exchange rate) ওঠানামাৰ প্ৰভাৱ আন্তঃজাতীয় ব্যৱসায়ত পৰা দেখা যায়।","title_as":"আন্তঃজাতীয় ব্যৱসায় বনাম ঘৰুৱা ব্যৱসায়","topic_slug_as":"আন্তঃজাতীয়-ব্যৱসায়-বনাম-ঘৰুৱা-ব্যৱসায়","definition_as":"আন্তঃজাতীয় ব্যৱসায়িক কামকাজ পৰিচালনা কৰাটো ঘৰুৱা ব্যৱসায়তকৈ জটিল। দুয়োৰ মাজৰ কিছু পাৰ্থক্য তলত উল্লেখ কৰা হ’ল: ১. ক্ৰেতা আৰু বিক্ৰেতাৰ জাতীয়তা: আন্তঃজাতীয় ব্যৱসায়ত ক্ৰেতা আৰু বিক্ৰেতা বেলেগে বেলেগ দেশৰ হয়, যাৰ ফলত পাৰস্পৰিক বুজাবুজি কম হ’ব পাৰে। ২. অন্যান্য স্বাৰ্থজড়িত পক্ষৰ জাতীয়তা: ব্যৱসায়িক প্ৰতিষ্ঠানৰ সৈতে জড়িত কৰ্মচাৰী, যোগানভিটাৰ, আৰু অন্যান্য অংশীদাৰৰ জাতীয়তা ভিন্ন হোৱাৰ বাবে প্ৰমূল্যবোধ আৰু আচৰণত ভিন্নতা দেখা যায়। ৩. নিয়ম-কানুন: আন্তঃজাতীয় ব্যৱসায়ত বিভিন্ন দেশৰ নিয়ম-কানুন, সংস্কৃতি আৰু ব্যৱসায়িক প্ৰথাৰ ভিন্নতাৰ বাবে জটিলতা সৃষ্টি হ’ব পাৰে। ৪. মুদ্ৰা: বিভিন্ন দেশৰ মুদ্ৰাৰ বিনিময় হাৰৰ (exchange rate) ওঠানামাৰ প্ৰভাৱ আন্তঃজাতীয় ব্যৱসায়ত পৰা দেখা যায়।","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a25e929473568d758063f8f' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'আন্তঃজাতীয়-ব্যৱসায়-বনাম-ঘৰুৱা-ব্যৱসায়' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'Assamese');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f64d8e6ddb2deb7d76-en-46","language":"English","title":"MSME and Business Entrepreneurship","topic_slug":"msme-and-business-entrepreneurship","definition":"MSME stands for Micro, Small and Medium Enterprises, which play a significant role in India''s economic development. MSME contributes significantly to the country''s exports, industrialisation, and employment generation. The sector offers a wide range of products, from simple consumer handicrafts to high-precision, sophisticated finished products.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f64d8e6ddb2deb7d76' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'msme-and-business-entrepreneurship' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f64d8e6ddb2deb7d76-en-47","language":"English","title":"Role of MSME in India","topic_slug":"role-of-msme-in-india","definition":"MSME is a vital link in the industrialisation process in terms of production, employment, and exports for economic prosperity. The sector is complementary to large industries as ancillary units and forms an integral part of the value chain for building a conducive environment for indigenous skills, grass root innovations, and entrepreneurship development. MSME dominates the industrial scenario in the country with a sizeable proportion of the labour force and tremendous export potential.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f64d8e6ddb2deb7d76' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'role-of-msme-in-india' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f64d8e6ddb2deb7d76-en-48","language":"English","title":"Definition of MSME","topic_slug":"definition-of-msme","definition":"The Government of India defines MSME based on investment in plant and machinery and turnover. The definition used by the Government of India to describe MSME is based on the investment in plant and machinery and turnover. Investment in Plant and Machinery: Small Enterprises: Does not exceed ₹50 crore Medium Enterprises: Does not exceed ₹250 crore % share of MSMEs in Small Enterprises: 0.52%","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f64d8e6ddb2deb7d76' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'definition-of-msme' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f64d8e6ddb2deb7d76-en-49","language":"English","title":"Village Industries","topic_slug":"village-industries","definition":"Village industry has been defined as any industry located in a rural area which produces any goods, renders any service with or without the use of power and in which the fixed capital investment per head or artisan or worker is specified by the central government, from time to time.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f64d8e6ddb2deb7d76' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'village-industries' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f64d8e6ddb2deb7d76-en-50","language":"English","title":"Role of MSME in Socio-Economic Development","topic_slug":"role-of-msme-in-socio-economic-development","definition":"MSME contributes to the socio-economic development of the country by providing employment opportunities, reducing income inequalities, and promoting dispersed development of industries and linkage with other sectors of the economy. The promotion of MSME and rural industrialisation has been considered by the Government of India as a powerful instrument for realising the twin objectives of ''accelerated industrial growth and creating additional productive employment potential in rural and backward areas''.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f64d8e6ddb2deb7d76' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'role-of-msme-in-socio-economic-development' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f64d8e6ddb2deb7d76-en-51","language":"English","title":"Contribution of MSME","topic_slug":"contribution-of-msme","definition":"The contribution of these village industries to the balanced regional development of our country is noteworthy. Small industries in India account for 95 per cent of the industrial units in the country. MSME are the second-largest employers of human resources, after agriculture. They generate more number of employment opportunities per unit of capital invested compared to large industries. MSME provide ample opportunity for entrepreneurship, and the latent skills and talents of people can be channelled into business ideas which can be converted into reality with little capital investment and almost nil formalities to start a small business.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f64d8e6ddb2deb7d76' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'contribution-of-msme' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f64d8e6ddb2deb7d76-en-52","language":"English","title":"Problems Faced by MSME","topic_slug":"problems-faced-by-msme","definition":"The problems faced by MSME include remote location with less developed infrastructural facilities, lack of managerial talent, poor quality, traditional technology, and inadequate availability of finance. The problems of exporting small-scale units include lack of adequate data on foreign markets, lack of market intelligence, exchange rate fluctuations, quality standards, and pre-shipment finance.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f64d8e6ddb2deb7d76' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'problems-faced-by-msme' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f64d8e6ddb2deb7d76-en-53","language":"English","title":"Proposals Associated with MSME","topic_slug":"proposals-associated-with-msme","definition":"The potential of MSME is often not realised fully, because of several problems related to size. The problems faced by MSME include non-availability of adequate finance to carry out its operations, lack of credit worthiness, and dependence on local financial resources which frequently lead to exploitation by money lenders.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f64d8e6ddb2deb7d76' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'proposals-associated-with-msme' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f64d8e6ddb2deb7d76-as-54","language":"Assamese","title":"এম.এছ.এম.ই. আৰু ব্যৱসায়িক উদ্যোগ","topic_slug":"এম-এছ-এম-ই-আৰু-ব্যৱসায়িক-উদ্যোগ","definition":"শিখনৰ উদ্দেশ্যসমূহ: এই পাঠটো অধ্যয়ন কৰাৰ পিছত আমি জানিবলৈ সক্ষম হ’ম: ভাৰতবৰ্ষত এম.এছ.এম.ই.-ৰ অর্থ আৰু প্ৰকৃতিৰ বিষয়ে বাখ্যা কৰিবলৈ। ভাৰতবৰ্ষত এম.এছ.এম.ই. উদ্যোগৰ ভূমিকা জানিবলৈ। ভাৰতবৰ্ষত এম.এছ.এম.ই.য়ে সন্মুখীন হোৱা সমস্যাসমূহ বিশ্লেষণ কৰিবলৈ। এম.এছ.এম.ই. উদ্যোগৰ ভূমিকা ব্যাখ্যা কৰিবলৈ। উদ্যোগীকৰণ: উদ্যোগীকৰণ হ’ল যিকোনো অৰ্থনৈতিক কাৰ্য্যকলাপৰ দ্বাৰা নিজৰ ব্যৱসায় স্থাপন কৰা প্ৰক্ৰিয়া। যিজন ব্যক্তিয়ে নিজৰ ব্যৱসায় স্থাপন কৰে, তেওঁক উদ্যোগী বুলি কোৱা হয়। এই ব্যৱসায়িক এককটোক উদ্যোগ বুলিও জনা যায়। উদ্যোগীকৰণ ভাৰতক এক শ্ৰেষ্ঠ অৰ্থনৈতিক শক্তি হিচাপে পৰিগণিত কৰিবলৈ সহায় কৰিছে। এম.এছ.এম.ই. (MSME) আৰু উদ্যোগীকৰণ: ক্ষুদ্ৰ, ক্ষুদ্ৰ আৰু মজলীয়া উদ্যোগ (MSME) অর্থনৈতিক আৰু উদ্যোগীক বিকাশৰ ক্ষেত্ৰত বিশেষ ভূমিকা পালন কৰে। এই উদ্যোগসমূহে উৎপাদন, নিয়োগ আৰু কৰ্মসংস্থানৰ বৃদ্ধিৰ লগতে আন্তর্জাতিক বাণিজ্যত ভাৰতবৰ্ষৰ স্থান সুদৃঢ় কৰাত সহায় কৰে। ২০০৬ চনত Micro, Small and Medium Enterprise (MSME) আইনখন ভাৰতবৰ্ষত বলৱৎ কৰা হয়।","title_as":"এম.এছ.এম.ই. আৰু ব্যৱসায়িক উদ্যোগ","topic_slug_as":"এম-এছ-এম-ই-আৰু-ব্যৱসায়িক-উদ্যোগ","definition_as":"শিখনৰ উদ্দেশ্যসমূহ: এই পাঠটো অধ্যয়ন কৰাৰ পিছত আমি জানিবলৈ সক্ষম হ’ম: ভাৰতবৰ্ষত এম.এছ.এম.ই.-ৰ অর্থ আৰু প্ৰকৃতিৰ বিষয়ে বাখ্যা কৰিবলৈ। ভাৰতবৰ্ষত এম.এছ.এম.ই. উদ্যোগৰ ভূমিকা জানিবলৈ। ভাৰতবৰ্ষত এম.এছ.এম.ই.য়ে সন্মুখীন হোৱা সমস্যাসমূহ বিশ্লেষণ কৰিবলৈ। এম.এছ.এম.ই. উদ্যোগৰ ভূমিকা ব্যাখ্যা কৰিবলৈ। উদ্যোগীকৰণ: উদ্যোগীকৰণ হ’ল যিকোনো অৰ্থনৈতিক কাৰ্য্যকলাপৰ দ্বাৰা নিজৰ ব্যৱসায় স্থাপন কৰা প্ৰক্ৰিয়া। যিজন ব্যক্তিয়ে নিজৰ ব্যৱসায় স্থাপন কৰে, তেওঁক উদ্যোগী বুলি কোৱা হয়। এই ব্যৱসায়িক এককটোক উদ্যোগ বুলিও জনা যায়। উদ্যোগীকৰণ ভাৰতক এক শ্ৰেষ্ঠ অৰ্থনৈতিক শক্তি হিচাপে পৰিগণিত কৰিবলৈ সহায় কৰিছে। এম.এছ.এম.ই. (MSME) আৰু উদ্যোগীকৰণ: ক্ষুদ্ৰ, ক্ষুদ্ৰ আৰু মজলীয়া উদ্যোগ (MSME) অর্থনৈতিক আৰু উদ্যোগীক বিকাশৰ ক্ষেত্ৰত বিশেষ ভূমিকা পালন কৰে। এই উদ্যোগসমূহে উৎপাদন, নিয়োগ আৰু কৰ্মসংস্থানৰ বৃদ্ধিৰ লগতে আন্তর্জাতিক বাণিজ্যত ভাৰতবৰ্ষৰ স্থান সুদৃঢ় কৰাত সহায় কৰে। ২০০৬ চনত Micro, Small and Medium Enterprise (MSME) আইনখন ভাৰতবৰ্ষত বলৱৎ কৰা হয়।","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f64d8e6ddb2deb7d76' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'এম-এছ-এম-ই-আৰু-ব্যৱসায়িক-উদ্যোগ' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'Assamese');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f44d8e6ddb2deb7d70-en-55","language":"English","title":"Public, Private and Global Enterprises","topic_slug":"public-private-and-global-enterprises","definition":"Business refers to economic activities aimed at earning profit through the production and sale of goods and services. It involves the systematic organization of resources to meet consumer needs. The chapter explores the classification of enterprises into public, private, and global sectors, highlighting their characteristics, roles, and significance in the economy. The learning objectives include understanding the features of public sector enterprises, the role of the government in different sectors, and the benefits of joint ventures.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f44d8e6ddb2deb7d70' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'public-private-and-global-enterprises' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f44d8e6ddb2deb7d70-en-56","language":"English","title":"Types of Enterprises","topic_slug":"types-of-enterprises","definition":"Public sector enterprises are owned and managed by the government. They include departmental undertakings, statutory corporations, and government companies. Private sector enterprises are owned and operated by individuals or private groups. They include sole proprietorships, partnerships, joint Hindu family businesses, cooperatives, and companies. Global enterprises, or multinational corporations, operate in multiple countries. They are characterized by their large scale, international presence, and cross-border operations.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f44d8e6ddb2deb7d70' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'types-of-enterprises' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f44d8e6ddb2deb7d70-en-57","language":"English","title":"Features of Public Sector Enterprises","topic_slug":"features-of-public-sector-enterprises","definition":"Government ownership: Public sector enterprises are fully or partially owned by the government, ensuring control over critical economic activities. Accountability: These enterprises are accountable to the public and must adhere to government policies and regulations. Social welfare focus: They prioritize social welfare and economic development over profit maximization, especially in sectors like healthcare, education, and infrastructure. Long-term planning: Public enterprises often focus on long-term national goals, such as industrialization and regional development. Limited competition: They may operate in sectors where private enterprises are not viable or where government control is essential for national interests.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f44d8e6ddb2deb7d70' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'features-of-public-sector-enterprises' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f44d8e6ddb2deb7d70-en-58","language":"English","title":"Departmental Undertakings","topic_slug":"departmental-undertakings","definition":"Departmental undertakings are the oldest form of public sector enterprises, established as part of government departments. Examples include the Indian Railways and the Department of Posts. They are directly managed by government ministries, with decisions made by civil servants rather than independent boards. These enterprises are funded by the government treasury and their profits are deposited back into the public exchequer. They face challenges such as lack of operational flexibility, bureaucratic delays, and limited autonomy in decision-making. Despite these limitations, they ensure direct government control over essential services and maintain a strong public accountability mechanism.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f44d8e6ddb2deb7d70' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'departmental-undertakings' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f44d8e6ddb2deb7d70-en-59","language":"English","title":"Statutory Corporations","topic_slug":"statutory-corporations","definition":"Statutory corporations are established by a special act of Parliament, granting them a separate legal identity. Examples include the Life Insurance Corporation (LIC) and the Food Corporation of India (FCI). They operate independently with their own boards of directors, ensuring a balance between government oversight and operational autonomy. These corporations are funded through their own revenues, generated from the sale of goods/services, rather than direct government grants. They have the authority to enter into contracts, own property, and sue or be sued in their own name. Statutory corporations are subject to specific laws and regulations, which define their objectives, functions, and financial management.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f44d8e6ddb2deb7d70' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'statutory-corporations' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f44d8e6ddb2deb7d70-en-60","language":"English","title":"Government Companies","topic_slug":"government-companies","definition":"Government companies are incorporated under the Companies Act and have the government as a majority shareholder. Examples include Bharat Heavy Electricals Limited (BHEL) and Steel Authority of India Limited (SAIL). They operate as separate legal entities with their own management structures, though the government holds significant control through shareholding. These companies aim to balance profitability with public welfare, often operating in strategic sectors like energy, steel, and defense. They enjoy greater operational flexibility compared to departmental undertakings, as they are managed by professional administrators. The government may acquire or divest shares in these companies based on economic and policy considerations.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f44d8e6ddb2deb7d70' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'government-companies' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f44d8e6ddb2deb7d70-en-61","language":"English","title":"Role of the Public Sector","topic_slug":"role-of-the-public-sector","definition":"The public sector plays a crucial role in providing essential services, such as transportation, healthcare, and education, which may not be efficiently managed by the private sector. It ensures equitable distribution of resources and promotes inclusive growth by focusing on underdeveloped regions and marginalized communities. The public sector acts as a regulator and stabilizer in the economy, especially during crises or periods of economic instability. It supports the development of critical industries and infrastructure, which are vital for long-term economic growth. The government may intervene in the public sector to correct market failures, protect national interests, and achieve socio-economic objectives.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f44d8e6ddb2deb7d70' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'role-of-the-public-sector' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f44d8e6ddb2deb7d70-en-62","language":"English","title":"Privatization and Disinvestment","topic_slug":"privatization-and-disinvestment","definition":"Privatization involves transferring ownership or management of public sector enterprises to the private sector to improve efficiency and reduce government burden. Disinvestment refers to the sale of government equity in public sector companies to raise funds and attract private investment. The government may privatize certain enterprises to reduce fiscal deficits, enhance operational efficiency, and promote competition. Privatization can lead to improved management practices, better customer service, and increased innovation in the private sector. However, it may also result in reduced public accountability, potential job losses, and the risk of monopolistic practices.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f44d8e6ddb2deb7d70' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'privatization-and-disinvestment' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f44d8e6ddb2deb7d70-en-63","language":"English","title":"Global Enterprises","topic_slug":"global-enterprises","definition":"Global enterprises, or multinational corporations (MNCs), operate across multiple countries, leveraging resources and markets worldwide. Examples include Coca-Cola, Toyota, and Samsung. They are characterized by their large scale, advanced technology, and global supply chains, enabling them to compete internationally. These enterprises often invest in foreign markets through foreign direct investment (FDI), establishing subsidiaries or joint ventures. Global enterprises contribute to economic growth by creating jobs, transferring technology, and enhancing trade between countries. They face challenges such as cultural differences, regulatory complexities, and the need to adapt to diverse market conditions.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f44d8e6ddb2deb7d70' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'global-enterprises' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f44d8e6ddb2deb7d70-en-64","language":"English","title":"Joint Ventures","topic_slug":"joint-ventures","definition":"A joint venture is a strategic partnership between two or more entities to undertake a specific business activity. It combines the resources, expertise, and market access of the partners. Benefits of joint ventures include shared risks, access to new markets, and the ability to pool technological and managerial resources. They allow companies to enter foreign markets with reduced risks and costs, as the partners share responsibilities and profits. Joint ventures can lead to innovation and efficiency by integrating complementary strengths of the participating entities. However, they may face challenges such as conflicts in management, differences in corporate culture, and the need for effective coordination.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f44d8e6ddb2deb7d70' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'joint-ventures' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f44d8e6ddb2deb7d70-en-65","language":"English","title":"Mixed Economy","topic_slug":"mixed-economy","definition":"A mixed economy combines elements of both public and private sectors, allowing the government and private enterprises to coexist and complement each other. The Indian economy is a mixed economy, where the government plays a significant role in key sectors while allowing private enterprises to operate in other areas. This model aims to balance economic efficiency with social welfare, ensuring that essential services are provided while encouraging private sector growth. The government may regulate private enterprises to prevent exploitation, ensure fair competition, and protect consumer interests. The balance between public and private sectors can vary over time, depending on economic policies and developmental goals.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f44d8e6ddb2deb7d70' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'mixed-economy' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f44d8e6ddb2deb7d70-as-66","language":"Assamese","title":"বিভাগীয় সংগঠন","topic_slug":"বিভাগীয়-সংগঠন","definition":"এই উদ্যোগবোৰৰ পুঁজি চৰকাৰী নিধিৰ পৰা আহে। সংসদৰ দ্বাৰা চৰকাৰী বাৰ্ষিক বাজেটত আবণ্টনৰ দ্বাৰা ইয়াৰ ধন আছুতীয়াকৈ ৰখা হয়। এইবোৰ উদ্যোগ চৰকাৰী মন্ত্ৰণালয়ৰ এটা অংশৰ দৰে কাম কৰে আৰু মন্ত্ৰণালয়ৰ নিয়ন্ত্ৰণত থাকে। বৈশিষ্ট্যসমূহ: চৰকাৰী নিধিৰ পৰা পুঁজি আহিছে। চৰকাৰী হিচাপ পৰীক্ষা নিয়ন্ত্ৰণ ইয়াতো প্রযোজ্য। কৰ্মচাৰীসকল চৰকাৰী চাকৰিয়াল। মন্ত্ৰণালয়ৰ প্রত্যক্ষ নিয়ন্ত্ৰণত থাকে। গ্ৰাহকৰ প্ৰয়োজনীয়তাৰ প্ৰতি সংবেদনশীল নহয়। সুবিধা: কাম-কাজৰ ওপৰত ফলপ্রসূ নিয়ন্ত্ৰণ ৰখাৰ সুবিধা। উচ্চ মাত্ৰাৰ ৰাজহুৱা দায়বদ্ধতা নিশ্চিত কৰে। উদ্যোগৰ উপাৰ্জিত ৰাজহ চৰকাৰী নিধিলৈ যায়। অসুবিধা: নমনীয়তা কম। সময়মতে সিদ্ধান্ত লোৱাত পলম হ’ব পাৰে। ব্যৱসায়িক সুবিধা লোৱাত অক্ষম। অতিরিক্ত আমোলাৰ প্ৰভাৱ।","title_as":"বিভাগীয় সংগঠন","topic_slug_as":"বিভাগীয়-সংগঠন","definition_as":"এই উদ্যোগবোৰৰ পুঁজি চৰকাৰী নিধিৰ পৰা আহে। সংসদৰ দ্বাৰা চৰকাৰী বাৰ্ষিক বাজেটত আবণ্টনৰ দ্বাৰা ইয়াৰ ধন আছুতীয়াকৈ ৰখা হয়। এইবোৰ উদ্যোগ চৰকাৰী মন্ত্ৰণালয়ৰ এটা অংশৰ দৰে কাম কৰে আৰু মন্ত্ৰণালয়ৰ নিয়ন্ত্ৰণত থাকে। বৈশিষ্ট্যসমূহ: চৰকাৰী নিধিৰ পৰা পুঁজি আহিছে। চৰকাৰী হিচাপ পৰীক্ষা নিয়ন্ত্ৰণ ইয়াতো প্রযোজ্য। কৰ্মচাৰীসকল চৰকাৰী চাকৰিয়াল। মন্ত্ৰণালয়ৰ প্রত্যক্ষ নিয়ন্ত্ৰণত থাকে। গ্ৰাহকৰ প্ৰয়োজনীয়তাৰ প্ৰতি সংবেদনশীল নহয়। সুবিধা: কাম-কাজৰ ওপৰত ফলপ্রসূ নিয়ন্ত্ৰণ ৰখাৰ সুবিধা। উচ্চ মাত্ৰাৰ ৰাজহুৱা দায়বদ্ধতা নিশ্চিত কৰে। উদ্যোগৰ উপাৰ্জিত ৰাজহ চৰকাৰী নিধিলৈ যায়। অসুবিধা: নমনীয়তা কম। সময়মতে সিদ্ধান্ত লোৱাত পলম হ’ব পাৰে। ব্যৱসায়িক সুবিধা লোৱাত অক্ষম। অতিরিক্ত আমোলাৰ প্ৰভাৱ।","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f44d8e6ddb2deb7d70' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'বিভাগীয়-সংগঠন' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'Assamese');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f44d8e6ddb2deb7d70-as-67","language":"Assamese","title":"বিধিৱদ্ধ নিগম","topic_slug":"বিধিৱদ্ধ-নিগম","definition":"বিধিৱদ্ধ নিগমবোৰ সংসদৰ বিশেষ আইনৰ দ্বাৰা গঠিত হয়। আইনখনত ইয়াৰ ক্ষমতা, কাৰ্যাবলী আৰু নীতি-নিয়মৰ সংজ্ঞা দিয়া হয়। বৈশিষ্ট্যসমূহ: সংসদৰ আইনৰ দ্বাৰা গঠিত। নিজৰ নামত কাৰ্যক্ষম। চৰকাৰী বা ৰাইজৰ পৰা পুঁজি সংগ্ৰহ কৰিব পাৰে। স্বশাসিতভাৱে কাম কৰিব পাৰে। সুবিধা: চৰকাৰী বাজেটৰ ওপৰত নিৰ্ভৰশীল নহয়। নিজস্ব নীতি আৰু সিদ্ধান্ত লোৱাৰ ক্ষমতা থাকে। বিশেষ উদ্দেশ্য পূৰণৰ বাবে উপযোগী। অসুবিধা: অতিরিক্ত আনুষ্ঠানিকতা। সময়মতে সিদ্ধান্ত লোৱাত পলম হ’ব পাৰে। দায়িত্ব নিৰ্ধাৰণ কৰাটো কঠিন হ’ব পাৰে।","title_as":"বিধিৱদ্ধ নিগম","topic_slug_as":"বিধিৱদ্ধ-নিগম","definition_as":"বিধিৱদ্ধ নিগমবোৰ সংসদৰ বিশেষ আইনৰ দ্বাৰা গঠিত হয়। আইনখনত ইয়াৰ ক্ষমতা, কাৰ্যাবলী আৰু নীতি-নিয়মৰ সংজ্ঞা দিয়া হয়। বৈশিষ্ট্যসমূহ: সংসদৰ আইনৰ দ্বাৰা গঠিত। নিজৰ নামত কাৰ্যক্ষম। চৰকাৰী বা ৰাইজৰ পৰা পুঁজি সংগ্ৰহ কৰিব পাৰে। স্বশাসিতভাৱে কাম কৰিব পাৰে। সুবিধা: চৰকাৰী বাজেটৰ ওপৰত নিৰ্ভৰশীল নহয়। নিজস্ব নীতি আৰু সিদ্ধান্ত লোৱাৰ ক্ষমতা থাকে। বিশেষ উদ্দেশ্য পূৰণৰ বাবে উপযোগী। অসুবিধা: অতিরিক্ত আনুষ্ঠানিকতা। সময়মতে সিদ্ধান্ত লোৱাত পলম হ’ব পাৰে। দায়িত্ব নিৰ্ধাৰণ কৰাটো কঠিন হ’ব পাৰে।","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f44d8e6ddb2deb7d70' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'বিধিৱদ্ধ-নিগম' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'Assamese');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f54d8e6ddb2deb7d73-en-68","language":"English","title":"Social Responsibilities of Business and Business Ethics","topic_slug":"social-responsibilities-of-business-and-business-ethics","definition":"Social responsibility of business refers to the obligation to take decisions and perform actions that are desirable in terms of the objectives and values of our society. It is the responsibility of business to respect social values and norms of behaviour, and to act with due concern for the effects on the lives of other people. Social responsibility is broader than legal responsibility, and involves an element of voluntary action on the part of business people for the benefit of society.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f54d8e6ddb2deb7d73' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'social-responsibilities-of-business-and-business-ethics' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f54d8e6ddb2deb7d73-en-69","language":"English","title":"Need for Social Responsibility","topic_slug":"need-for-social-responsibility","definition":"Every individual living in society has certain obligations towards society, and business enterprises are no exception. Business enterprises should do what is right and just, and not do anything that is undesirable from society''s point of view. Social responsibility is essential for the growth and prosperity of business, and for the well-being of society as a whole.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f54d8e6ddb2deb7d73' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'need-for-social-responsibility' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f54d8e6ddb2deb7d73-en-70","language":"English","title":"Social Responsibility towards Different Interest Groups","topic_slug":"social-responsibility-towards-different-interest-groups","definition":"Social responsibility is not just towards the owners of the business, but also towards other sections of society such as customers, employees, suppliers, government, and community. Business enterprises have a responsibility to serve the interests of all these groups, and to contribute to the achievement of their aspirations. By assuming social responsibility, business enterprises can improve their public image and gain long-term benefits.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f54d8e6ddb2deb7d73' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'social-responsibility-towards-different-interest-groups' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f54d8e6ddb2deb7d73-en-71","language":"English","title":"Relationship between Business and Environmental Protection","topic_slug":"relationship-between-business-and-environmental-protection","definition":"Business enterprises have a responsibility to protect the environment and to prevent pollution. Environmental protection is essential for the well-being of society, and business enterprises have a role to play in this. By adopting environmentally friendly practices, business enterprises can reduce their costs and improve their public image.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f54d8e6ddb2deb7d73' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'relationship-between-business-and-environmental-protection' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f54d8e6ddb2deb7d73-en-72","language":"English","title":"Concept of Business Ethics","topic_slug":"concept-of-business-ethics","definition":"Business ethics refers to the principles and values that guide the behaviour of business enterprises. Business ethics involves the application of moral principles to business decisions and actions. Business ethics is essential for the growth and prosperity of business, and for the well-being of society as a whole.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f54d8e6ddb2deb7d73' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'concept-of-business-ethics' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f54d8e6ddb2deb7d73-en-73","language":"English","title":"Elements of Business Ethics","topic_slug":"elements-of-business-ethics","definition":"Business ethics involves the consideration of the impact of business decisions and actions on all stakeholders, including customers, employees, suppliers, government, and community. Business ethics involves the adoption of practices that are fair, honest, and transparent. Business ethics involves the respect for human rights and dignity, and the protection of the environment.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f54d8e6ddb2deb7d73' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'elements-of-business-ethics' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f54d8e6ddb2deb7d73-en-74","language":"English","title":"Corporate Social Responsibility","topic_slug":"corporate-social-responsibility","definition":"CSR refers to the role that companies can play in meeting the ''agenda of sustainable development. CSR involves a balanced approach to economic progress, social progress, and environmental protection. CSR is essential for the growth and prosperity of business, and for the well-being of society as a whole.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f54d8e6ddb2deb7d73' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'corporate-social-responsibility' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f54d8e6ddb2deb7d73-en-75","language":"English","title":"Arguments for Social Responsibility","topic_slug":"arguments-for-social-responsibility","definition":"Social responsibility is essential for the growth and prosperity of business. Social responsibility is necessary for the well-being of society as a whole. Social responsibility involves the consideration of the impact of business decisions and actions on all stakeholders. Social responsibility involves the adoption of practices that are fair, honest, and transparent. Social responsibility involves the respect for human rights and dignity, and the protection of the environment.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f54d8e6ddb2deb7d73' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'arguments-for-social-responsibility' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f54d8e6ddb2deb7d73-en-76","language":"English","title":"CSR in India","topic_slug":"csr-in-india","definition":"The concept of CSR in India is governed by Clause 135 of the Companies Act, 2013. The CSR provisions within the Act are applicable to companies with an annual turnover of 1,000 crore and more, or a net worth of Rs. 500 crore and more, or a net profit of Rs. 5 crore and more. The Act encourages companies to spend at least 2% of their average net profit in the previous three years on CSR activities.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f54d8e6ddb2deb7d73' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'csr-in-india' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f64d8e6ddb2deb7d75-en-77","language":"English","title":"Internal Sources of Finance","topic_slug":"internal-sources-of-finance","definition":"Internal sources of finance refer to the funds generated within the business itself. These sources include: - Retained Earnings: Profits earned by the business are retained and reinvested in the business. - Dividend: A portion of the profits is distributed to the shareholders in the form of dividends. - Sale of Assets: The business can sell its assets, such as property, equipment, or inventory, to generate funds.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f64d8e6ddb2deb7d75' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'internal-sources-of-finance' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f64d8e6ddb2deb7d75-en-78","language":"English","title":"External Sources of Finance","topic_slug":"external-sources-of-finance","definition":"External sources of finance refer to the funds obtained from outside the business. These sources include: - Share Capital: The business can issue shares to the public to raise funds. - Debentures: The business can issue debentures to raise long-term funds. - Loans: The business can borrow money from banks, financial institutions, or other lenders. - Venture Capital: The business can obtain funds from venture capitalists who invest in new and innovative businesses. - Angel Investors: The business can obtain funds from angel investors who provide financial support to start-ups and small businesses. - Factoring: The business can sell its receivables to a factor who provides immediate cash. - Hire Purchase: The business can purchase assets on hire-purchase basis, where the asset is paid for in installments.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f64d8e6ddb2deb7d75' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'external-sources-of-finance' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f64d8e6ddb2deb7d75-en-79","language":"English","title":"Government Assistance","topic_slug":"government-assistance","definition":"The government provides various forms of assistance to businesses, including: - Subsidies: The government provides subsidies to businesses to help them overcome financial difficulties. - Grants: The government provides grants to businesses to support their growth and development. - Tax Incentives: The government provides tax incentives to businesses to encourage them to invest in certain areas. - Loans: The government provides loans to businesses at concessional rates of interest.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f64d8e6ddb2deb7d75' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'government-assistance' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f64d8e6ddb2deb7d75-en-80","language":"English","title":"Other Sources of Finance","topic_slug":"other-sources-of-finance","definition":"Other sources of finance include: - Crowdfunding: The business can raise funds from a large number of people through crowdfunding platforms. - Peer-to-Peer Lending: The business can borrow money from individuals through peer-to-peer lending platforms. - Asset-Based Finance: The business can raise funds by using its assets as collateral.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f64d8e6ddb2deb7d75' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'other-sources-of-finance' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f64d8e6ddb2deb7d75-as-81","language":"Assamese","title":"পাতনি","topic_slug":"পাতনি","definition":"ব্যৱসায় আৰম্ভ কৰিবলৈ বিভিন্ন সংগঠনৰ বিভত বা বিভ্তৰ লগত জড়িত দিশক আলোচনা কৰা হয়। এই পাঠত বিভিন্ন পৃষ্ঠৰ আশা হয়। সেই বিভ্তৰ উৎসসমূহৰ সুবিধা আৰু সীমাবদ্ধতাসমূহ যিকোনো ব্যৱসায়ত কোৱা হয়। ব্যৱসায়ত বিভিন্ন কাৰ্য চলাই নিবলৈ যি ধনৰ প্ৰয়োজন হয় তাকে ব্যৱসায় বিভ বোলা হয়। বিভিন্ন উৎসৰ পৰা কেনেকৈ ধন সংগ্ৰহ কৰা হয় সেই বিষয়ে তেওঁ ইয়াক জনাটো অতি আৱশ্যক। আকৌ বিভ্তৰ উৎসৰ উপযুক্ত বাছনিৰ ক্ষেত্ৰত উদ্যোক্তা এজনে আৰম্ভণিতে যি মূল ধনেৰে ব্যৱসায় আৰম্ভ কৰে ভৱিষ্যতে ইয়াক চলাই নিবলৈ যথেষ্ঠ নহয়। সেই কাৰণে এজন পৰিচালক আদিয়ে বিত্তীয় প্রয়োজন পূৰাবৰ বাবে আৱশ্যকীয় পৰিকল্পনা যুগুত কৰে। ব্যৱসায় বিভ্তই ব্যৱসায় খণ্ডৰ উৎপাদন, বিতৰণ আৰু সেৱাৰ লগত জড়িত সকলো ৰূপৰ ব্যৱসায়ৰ বাবে বিত্তীয় প্ৰয়োজনতে স্থায়ী সম্পত্তিৰ প্ৰয়োজনতে ওৰ নপৰে। সৰু বৰ সকলোবোৰ প্ৰতিষ্ঠানৰ বাবে দৈনন্দিন পৰিচালনাৰবাবে বিত্তৰ অতিপ্ৰয়োজন। ইয়াকে ব্যৱসায়িক প্রতিষ্ঠানৰ কাৰ্যকৰী মূলধন (working capital) বুলি জনা যায়। এই সম্পত্তিয়ে ব্যৱসায়িক কাৰ্যকলাপ সচল ৰাখে।","title_as":"পাতনি","topic_slug_as":"পাতনি","definition_as":"ব্যৱসায় আৰম্ভ কৰিবলৈ বিভিন্ন সংগঠনৰ বিভত বা বিভ্তৰ লগত জড়িত দিশক আলোচনা কৰা হয়। এই পাঠত বিভিন্ন পৃষ্ঠৰ আশা হয়। সেই বিভ্তৰ উৎসসমূহৰ সুবিধা আৰু সীমাবদ্ধতাসমূহ যিকোনো ব্যৱসায়ত কোৱা হয়। ব্যৱসায়ত বিভিন্ন কাৰ্য চলাই নিবলৈ যি ধনৰ প্ৰয়োজন হয় তাকে ব্যৱসায় বিভ বোলা হয়। বিভিন্ন উৎসৰ পৰা কেনেকৈ ধন সংগ্ৰহ কৰা হয় সেই বিষয়ে তেওঁ ইয়াক জনাটো অতি আৱশ্যক। আকৌ বিভ্তৰ উৎসৰ উপযুক্ত বাছনিৰ ক্ষেত্ৰত উদ্যোক্তা এজনে আৰম্ভণিতে যি মূল ধনেৰে ব্যৱসায় আৰম্ভ কৰে ভৱিষ্যতে ইয়াক চলাই নিবলৈ যথেষ্ঠ নহয়। সেই কাৰণে এজন পৰিচালক আদিয়ে বিত্তীয় প্রয়োজন পূৰাবৰ বাবে আৱশ্যকীয় পৰিকল্পনা যুগুত কৰে। ব্যৱসায় বিভ্তই ব্যৱসায় খণ্ডৰ উৎপাদন, বিতৰণ আৰু সেৱাৰ লগত জড়িত সকলো ৰূপৰ ব্যৱসায়ৰ বাবে বিত্তীয় প্ৰয়োজনতে স্থায়ী সম্পত্তিৰ প্ৰয়োজনতে ওৰ নপৰে। সৰু বৰ সকলোবোৰ প্ৰতিষ্ঠানৰ বাবে দৈনন্দিন পৰিচালনাৰবাবে বিত্তৰ অতিপ্ৰয়োজন। ইয়াকে ব্যৱসায়িক প্রতিষ্ঠানৰ কাৰ্যকৰী মূলধন (working capital) বুলি জনা যায়। এই সম্পত্তিয়ে ব্যৱসায়িক কাৰ্যকলাপ সচল ৰাখে।","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f64d8e6ddb2deb7d75' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'পাতনি' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'Assamese');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f64d8e6ddb2deb7d75-as-82","language":"Assamese","title":"বিত্তৰ উৎসৰ শ্ৰেণীবিভাগ","topic_slug":"বিত্তৰ-উৎসৰ-শ্ৰেণীবিভাগ","definition":"ব্যক্তিগত আৰু অংশীদাৰী ব্যৱসায়ত ব্যক্তিগত উৎস বা বেংকৰ খণ আৰু বৃদ্ধ বান্ধৰ পৰা সংগ্ৰহ কৰা হয়। যৌথ কোম্পানী সংগঠনত প্রয়োজন হোৱা বিত্তৰ প্ৰসাৰ আৰু সেইবোৰ তলত শ্ৰেণীবিভাগ কৰি দেখুওৱা হৈছে। ৮.৩.১ সময় ভিত্তিক: দীৰ্ঘকালীন উৎস, মধ্যকালীন উৎস আৰু হ্রস্বকালীন উৎস। ৮.৩.২ মালিকী স্বত্বৰ ভিত্তিত: মালিকৰ বিত্ত আৰু খণৰ উৎস। ৮.৩.৩ উৎসৰ ভিত্তিত: আভ্যন্তৰীণ উৎস আৰু বাহ্যিক উৎস।","title_as":"বিত্তৰ উৎসৰ শ্ৰেণীবিভাগ","topic_slug_as":"বিত্তৰ-উৎসৰ-শ্ৰেণীবিভাগ","definition_as":"ব্যক্তিগত আৰু অংশীদাৰী ব্যৱসায়ত ব্যক্তিগত উৎস বা বেংকৰ খণ আৰু বৃদ্ধ বান্ধৰ পৰা সংগ্ৰহ কৰা হয়। যৌথ কোম্পানী সংগঠনত প্রয়োজন হোৱা বিত্তৰ প্ৰসাৰ আৰু সেইবোৰ তলত শ্ৰেণীবিভাগ কৰি দেখুওৱা হৈছে। ৮.৩.১ সময় ভিত্তিক: দীৰ্ঘকালীন উৎস, মধ্যকালীন উৎস আৰু হ্রস্বকালীন উৎস। ৮.৩.২ মালিকী স্বত্বৰ ভিত্তিত: মালিকৰ বিত্ত আৰু খণৰ উৎস। ৮.৩.৩ উৎসৰ ভিত্তিত: আভ্যন্তৰীণ উৎস আৰু বাহ্যিক উৎস।","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f64d8e6ddb2deb7d75' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'বিত্তৰ-উৎসৰ-শ্ৰেণীবিভাগ' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'Assamese');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0f64d8e6ddb2deb7d75-as-83","language":"Assamese","title":"বিত্তৰ উৎসসমূহ","topic_slug":"বিত্তৰ-উৎসসমূহ","definition":"৮.৪.১ সঞ্চিত লাভ (Retained Earnings): এটা কোম্পানীয়ে ইয়াৰ অংশধাৰকসকলক সকলোবোৰ লভ্যাংশ বিতৰণ নকৰি ভৱিষ্যতৰ বাবে ইয়াৰ এটা অংশ ৰাখি থয়। ই আভ্যন্তৰীণ বিত্তৰ উৎস। সুবিধা: এটা ব্যৱসায়ী সংগঠনৰ স্থায়ী বিভ্তৰ উৎস। সুত লভ্যাংশ বিলিকৰণ আদি ব্যয়ৰ পৰা মুক্ত। আভ্যন্তৰীণভাৱে সংগৃহিত হোৱাৰ বাবে অধিক স্বাধীনতা প্রদান কৰে। ব্যৱসায়ৰ অপ্রত্যাশিত ক্ষতিবহন কৰাৰ ক্ষমতা বৃদ্ধি কৰে। সীমাবদ্ধতা: অধিক মাত্ৰাত লাভৰ পুনৰ বিনিয়োগে অংশধাৰকসকলক অসন্তুষ্ট কৰিব পাৰে। লাভৰ পৰিমাণ কম-বেছি হোৱাৰ বাবে অনিশ্চিত। ৮.৪.২ ব্যৱসায়িক খণ (Trade Credit): এজন ব্যৱসায়ীয়ে আন এজন ব্যৱসায়িলৈ বাকীত পন্য আৰু সেৱা যোগান ধৰা। সুবিধা: সুবিধাজনক বিভ্তৰ উৎস। বিক্ৰেতা প্ৰতিষ্ঠানে গ্ৰাহকৰ খণযোগ্যতা সম্পর্কে অবহিত হ’ব পাৰে। ব্যৱসায়িক খণৰ সহজলভ্যতাই এটা প্রতিষ্ঠানক অতি বাণিজ্যৰ প্রতি প্রৰোচিত কৰিব পাৰে। সীমাবদ্ধতা: ব্যৱসায়িক খণৰ সহজলভ্যতাই এটা প্রতিষ্ঠানক অতি বাণিজ্যৰ প্রতি প্রৰোচিত কৰিব পাৰে। ব্যৱসায়িক খণৰ মাধ্যমত সীমিত পুঁজিহে সংগ্ৰহ কৰিব পৰা যায়।","title_as":"বিত্তৰ উৎসসমূহ","topic_slug_as":"বিত্তৰ-উৎসসমূহ","definition_as":"৮.৪.১ সঞ্চিত লাভ (Retained Earnings): এটা কোম্পানীয়ে ইয়াৰ অংশধাৰকসকলক সকলোবোৰ লভ্যাংশ বিতৰণ নকৰি ভৱিষ্যতৰ বাবে ইয়াৰ এটা অংশ ৰাখি থয়। ই আভ্যন্তৰীণ বিত্তৰ উৎস। সুবিধা: এটা ব্যৱসায়ী সংগঠনৰ স্থায়ী বিভ্তৰ উৎস। সুত লভ্যাংশ বিলিকৰণ আদি ব্যয়ৰ পৰা মুক্ত। আভ্যন্তৰীণভাৱে সংগৃহিত হোৱাৰ বাবে অধিক স্বাধীনতা প্রদান কৰে। ব্যৱসায়ৰ অপ্রত্যাশিত ক্ষতিবহন কৰাৰ ক্ষমতা বৃদ্ধি কৰে। সীমাবদ্ধতা: অধিক মাত্ৰাত লাভৰ পুনৰ বিনিয়োগে অংশধাৰকসকলক অসন্তুষ্ট কৰিব পাৰে। লাভৰ পৰিমাণ কম-বেছি হোৱাৰ বাবে অনিশ্চিত। ৮.৪.২ ব্যৱসায়িক খণ (Trade Credit): এজন ব্যৱসায়ীয়ে আন এজন ব্যৱসায়িলৈ বাকীত পন্য আৰু সেৱা যোগান ধৰা। সুবিধা: সুবিধাজনক বিভ্তৰ উৎস। বিক্ৰেতা প্ৰতিষ্ঠানে গ্ৰাহকৰ খণযোগ্যতা সম্পর্কে অবহিত হ’ব পাৰে। ব্যৱসায়িক খণৰ সহজলভ্যতাই এটা প্রতিষ্ঠানক অতি বাণিজ্যৰ প্রতি প্রৰোচিত কৰিব পাৰে। সীমাবদ্ধতা: ব্যৱসায়িক খণৰ সহজলভ্যতাই এটা প্রতিষ্ঠানক অতি বাণিজ্যৰ প্রতি প্রৰোচিত কৰিব পাৰে। ব্যৱসায়িক খণৰ মাধ্যমত সীমিত পুঁজিহে সংগ্ৰহ কৰিব পৰা যায়।","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0f64d8e6ddb2deb7d75' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'বিত্তৰ-উৎসসমূহ' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'Assamese');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3be1-en-84","language":"English","title":"Price Ceiling","topic_slug":"price-ceiling","definition":"A price ceiling is a government-imposed maximum price (legal price) that is set below the equilibrium price. The price is not allowed to rise above this ceiling. Purpose: To make essential goods affordable to consumers (e.g., food, medicines, rent). Effect: - At the ceiling price (Pc Quantity supplied - Shortage (Excess Demand) is created - Black markets may emerge (goods sold illegally at higher prices) - Rationing may be introduced (e.g., ration cards) Examples in India: - Essential Commodities Act - Maximum retail prices (MRP) on medicine - Fair Price Shops (PDS) – government subsidised food prices Problems of Price Ceiling: 1. Creates shortages 2. Encourages black marketing 3. May reduce quality of goods 4. Requires rationing mechanisms","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3be1' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'price-ceiling' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3be1-en-85","language":"English","title":"Price Floor","topic_slug":"price-floor","definition":"A price floor is a government-imposed minimum price that is set above the equilibrium price. Price cannot fall below this floor. Purpose: To protect producers from low prices (e.g., farmers, labour minimum wage). Effect: - At the floor price (Pf Pe): Quantity supplied Quantity demanded - Surplus (Excess Supply) is created - Government may need to purchase the surplus Examples in India: - Minimum Support Price (MSP) for farmers: Government guarantees a minimum price for agricultural produce (wheat, rice, etc.) - Minimum Wage Law: Ensures workers are paid at least a minimum wage (floor on wage price) Problems of Price Floor: 1. Creates surplus / excess supply 2. Government has to buy up surplus (costly) 3. May discourage efficiency 4.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3be1' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'price-floor' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0ec4d8e6ddb2deb7d52-en-86","language":"English","title":"Primary Data","topic_slug":"primary-data","definition":"Primary data are data collected for the first time, directly from the source (original data). They are specifically collected for a particular investigation. Methods of collecting primary data: 1. Direct Personal Interview 2. Indirect Oral Interview 3. Questionnaire method (mailed) 4. Schedules filled by enumerators 5. Observation method Merits of Primary Data: - More reliable and accurate - Specific to the purpose - Current and up-to-date - Collected under controlled conditions Demerits: - Time-consuming and expensive - Requires trained personnel - Scope is limited to one study","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0ec4d8e6ddb2deb7d52' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'primary-data' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0ec4d8e6ddb2deb7d52-en-87","language":"English","title":"Secondary Data","topic_slug":"secondary-data","definition":"Secondary data are data that have already been collected by someone else for some other purpose and are now being used by the researcher. Sources of secondary data: - Government publications (RBI, CSO, NSSO reports) - International organisations (UN, World Bank, IMF) - Journals and academic papers - Newspapers and magazines - Websites and databases Merits: - Less expensive and time-saving - Wide coverage - Historical data available Demerits: - May not fit the current purpose - Reliability must be checked - May be outdated - Difficult to know collection methods","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0ec4d8e6ddb2deb7d52' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'secondary-data' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0ec4d8e6ddb2deb7d52-en-88","language":"English","title":"Methods of Collection","topic_slug":"methods-of-collection","definition":"For Primary Data: 1. Direct Personal Investigation: Investigator personally gathers information; accurate but costly and limited in scope. 2. Indirect Oral Investigation: Information obtained through third parties (witnesses, experts); suitable when direct data is difficult. 3. Information from Correspondents: Local agents or correspondents send data; suitable for newspapers and government data. 4. Mailed Questionnaire: Questionnaire sent by post; covers large area but low response rate. 5. Schedules through Enumerators: Trained enumerators fill schedules; more reliable, used in Census.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0ec4d8e6ddb2deb7d52' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'methods-of-collection' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0ec4d8e6ddb2deb7d52-en-89","language":"English","title":"Census Method","topic_slug":"census-method","definition":"The Census Method (Complete Enumeration) involves collecting data from every single unit of the population (universe). Example: Population Census of India — every household is surveyed. Merits: - Comprehensive and accurate - No sampling error - Useful when population is small or data must be exhaustive Demerits: - Very expensive and time-consuming - Not feasible for very large populations - Requires large number of trained investigators","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0ec4d8e6ddb2deb7d52' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'census-method' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0ec4d8e6ddb2deb7d52-en-90","language":"English","title":"Sample Survey","topic_slug":"sample-survey","definition":"A Sample Survey involves collecting data from only a portion (sample) of the population and using it to make inferences about the whole population. Merits: - Less expensive and faster - Feasible for large populations - Can be used for destructive testing - More detailed information per unit Demerits: - Sampling error is present - Requires careful selection of sample - Results may not perfectly represent the whole population Methods of Sampling: - Random Sampling: Every unit has an equal chance of selection - Stratified Sampling: Population divided into strata; random selection from each stratum - Systematic Sampling: Every nth unit is selected - Cluster Sampling: Population divided into clusters; some clusters fully surveyed","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0ec4d8e6ddb2deb7d52' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'sample-survey' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0ec4d8e6ddb2deb7d52-en-91","language":"English","title":"Census of India","topic_slug":"census-of-india","definition":"The Census of India is the largest data collection exercise in the world. It is conducted every 10 years. - First comprehensive Census: 1881 - Latest Census: 2011 (2021 Census delayed due to COVID-19) - Provides data on population, age, sex, literacy, occupation, housing, etc. - Conducted by the Office of the Registrar General of India (RGI) Key data from Census 2011: - Population: 1.21 billion - Literacy rate: 74% - Sex ratio: 940 females per 1000 males","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0ec4d8e6ddb2deb7d52' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'census-of-india' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0ec4d8e6ddb2deb7d52-en-92","language":"English","title":"National Sample Survey Organisation","topic_slug":"national-sample-survey-organisation","definition":"The National Sample Survey Office (NSSO) is a government organisation that conducts nationwide surveys on various socio-economic topics. - Established: 1950 - Conducts annual surveys on employment, income, consumer expenditure, health, education - Major surveys: NSS Employment-Unemployment Survey, Household Consumer Expenditure Survey - Data is used for government planning and policy-making Important NSSO surveys: - Periodic Labour Force Survey (PLFS) — employment and wages - Household Consumer Expenditure Survey (HCE) — poverty estimation --- AHSEC HS 1st Year Economics – Collection of Data chapter.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0ec4d8e6ddb2deb7d52' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'national-sample-survey-organisation' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0ee4d8e6ddb2deb7d57-en-93","language":"English","title":"Meaning of Correlation","topic_slug":"meaning-of-correlation","definition":"Correlation measures the degree and direction of the linear relationship between two variables. When two variables tend to move together, they are said to be correlated. Examples: - Height and weight (positive correlation) - Price and demand (negative correlation) - Shoe size and intelligence (no correlation) Types of Correlation: Based on Direction: - Positive Correlation: Both variables move in the same direction (X↑ → Y↑) - Negative Correlation: Variables move in opposite directions (X↑ → Y↓) Based on Degree: - Perfect Positive (r = +1): Exact linear relationship, positive direction - Perfect Negative (r = -1): Exact linear relationship, negative direction - Zero Correlation (r = 0): No linear relationship Based on Nature: - Linear: Relationship is a straight line - Non-linear (Curvilinear): Relationship is a curve","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0ee4d8e6ddb2deb7d57' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'meaning-of-correlation' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0ee4d8e6ddb2deb7d57-en-94","language":"English","title":"Properties of Correlation","topic_slug":"properties-of-correlation","definition":"Range: Correlation coefficient (r) lies between -1 and +1: -1 ≤ r ≤ +1 2. Dimensionless: r has no units 3. Symmetrical: Correlation of X with Y = Correlation of Y with X 4. Not affected by change of origin or scale (for Pearson''s r) 5. Independent of units of measurement","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0ee4d8e6ddb2deb7d57' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'properties-of-correlation' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0ee4d8e6ddb2deb7d57-en-95","language":"English","title":"Scatter Diagram","topic_slug":"scatter-diagram","definition":"A scatter diagram (scatter plot) is a graphical method of studying correlation. Values of both variables are plotted as dots on a graph. Interpretation: - Upward sloping cloud of dots → Positive correlation - Downward sloping cloud → Negative correlation - Random scatter → No correlation - Dots on a perfect line → Perfect correlation (r = ±1) - Oval/elliptical cloud → Moderate correlation Merits: Simple, visual, doesn''t assume linearity. Demerits: Doesn''t give exact value of correlation.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0ee4d8e6ddb2deb7d57' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'scatter-diagram' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0ee4d8e6ddb2deb7d57-en-96","language":"English","title":"Karl Pearson''s Coefficient of Correlation","topic_slug":"karl-pearson-s-coefficient-of-correlation","definition":"Karl Pearson''s method gives a precise numerical value of correlation for quantitative data. Formula: r = Σ(dx)(dy) / √[Σdx² × Σdy²] Where: - dx = X – X̄ (deviation of X from mean) - dy = Y – Ȳ (deviation of Y from mean) Alternative formula (actual mean method): r = [n·ΣXY – ΣX·ΣY] / √[(nΣX² – (ΣX)²)(nΣY² – (ΣY)²)] Interpretation of r: - r = +1: Perfect positive correlation - r = -1: Perfect negative correlation - 0.75 ≤ r < 1: High correlation - 0.5 ≤ r < 0.75: Moderate correlation - 0.25 ≤ r < 0.5: Low correlation - r < 0.25: Negligible correlation - r = 0: No linear correlation Assumptions: 1. Variables are linearly related 2. Normal distribution of variables 3. Quantitative data","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0ee4d8e6ddb2deb7d57' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'karl-pearson-s-coefficient-of-correlation' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0ee4d8e6ddb2deb7d57-en-97","language":"English","title":"Spearman''s Rank Correlation","topic_slug":"spearman-s-rank-correlation","definition":"Spearman''s Rank Correlation is used when data is available in rank form, or when data is qualitative, or when the relationship is not linear. Formula: rs = 1 – [6·ΣD² / n(n² – 1)] Where: - D = Difference between ranks of corresponding values (R1 – R2) - n = Number of paired observations Steps: 1. Assign ranks to both variables (1 = highest or lowest, consistently) 2. Find D = R1 – R2 for each pair 3. Calculate D² 4. Apply formula When ranks are tied: Assign the average of the tied ranks. Interpretation: Same as Pearson''s r (-1 to +1). Merits: Can be used for ordinal data; not affected by outliers; simpler to calculate. Demerits: Less precise than Pearson''s for quantitative data; loses information by using only ranks. --- AHSEC HS 1st Year Economics – Correlation chapter.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0ee4d8e6ddb2deb7d57' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'spearman-s-rank-correlation' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bdc-en-98","language":"English","title":"Total Fixed Cost","topic_slug":"total-fixed-cost","definition":"Fixed costs are costs that do not change with the level of output. They must be paid even when output is zero. Examples: Rent, interest on loans, insurance, depreciation, salaries of permanent staff. TFC is a horizontal straight line parallel to the X-axis (output axis).","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bdc' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'total-fixed-cost' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bdc-en-99","language":"English","title":"Total Variable Cost","topic_slug":"total-variable-cost","definition":"Variable costs change with the level of output. At zero output, TVC = 0. Examples: Raw materials, electricity, wages of temporary workers. TVC initially increases at a decreasing rate (increasing returns), then at an increasing rate (diminishing returns). TVC has an S-shape.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bdc' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'total-variable-cost' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bdc-en-100","language":"English","title":"Average Cost","topic_slug":"average-cost","definition":"Average Cost (also called Average Total Cost, ATC) is the cost per unit of output. AC = TC / Q = AFC + AVC The AC curve is U-shaped: - Falls initially (due to spreading of fixed costs + increasing returns) - Reaches minimum at the optimum output - Rises thereafter (due to diminishing returns)","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bdc' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'average-cost' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bdc-en-101","language":"English","title":"Marginal Cost","topic_slug":"marginal-cost","definition":"Marginal Cost is the additional cost incurred by producing one more unit of output. MC = ΔTC / ΔQ = ΔTVC / ΔQ (Note: Fixed costs do not change with output, so MC depends only on variable costs.) MC Curve is U-shaped: - Falls initially (increasing returns) - Reaches minimum - Rises (diminishing returns) MC cuts both AVC and AC at their minimum points (from below).","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bdc' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'marginal-cost' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bdc-en-102","language":"English","title":"Long Run Cost","topic_slug":"long-run-cost","definition":"In the long run, all costs are variable. The Long Run Average Cost (LRAC) curve is derived from the envelope of all short-run AC curves. The LRAC is also U-shaped (but flatter): - Falling LRAC: Economies of scale - Minimum LRAC: Optimum scale - Rising LRAC: Diseconomies of scale","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bdc' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'long-run-cost' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bdc-en-103","language":"English","title":"Cost Relationships","topic_slug":"cost-relationships","definition":"Relationship Explanation --- --- TC = TFC + TVC Basic cost identity AC = AFC + AVC Per-unit breakdown MC = ΔTVC/ΔQ Only variable costs change MC cuts AC at AC minimum Mathematical relationship AFC always falls Fixed cost spread over more units --- AHSEC HS 1st Year Economics – Cost Theory notes.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bdc' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'cost-relationships' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0ee4d8e6ddb2deb7d58-en-104","language":"English","title":"Meaning of Index Numbers","topic_slug":"meaning-of-index-numbers","definition":"An index number is a statistical measure designed to show changes in a variable (or group of variables) over time, with reference to a base period. Index Number = (Current Period Value / Base Period Value) × 100 The base period has index = 100. Example: If price of wheat was ₹20 in 2010 (base) and ₹30 in 2020, then price index = (30/20) × 100 = 150. This means prices have risen by 50%. Key features: - Expressed as a percentage - Relative measure of change - Base year index = 100","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0ee4d8e6ddb2deb7d58' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'meaning-of-index-numbers' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0ee4d8e6ddb2deb7d58-en-105","language":"English","title":"Construction of Index Numbers","topic_slug":"construction-of-index-numbers","definition":"Steps: 1. Choose base year: A normal year (no extreme events) 2. Select commodities: Decide which items to include (should be representative) 3. Collect price data: Current period and base period prices 4. Calculate index: Using appropriate method Methods of construction: 1. Simple (Unweighted) Price Index: P₀₁ = (ΣP₁ / ΣP₀) × 100 All items given equal weight. 2. Weighted Index – Laspeyres Method: P₀₁ = (ΣP₁Q₀ / ΣP₀Q₀) × 100 Base year quantities (Q₀) used as weights. 3. Weighted Index – Paasche''s Method: P₀₁ = (ΣP₁Q₁ / ΣP₀Q₁) × 100 Current year quantities (Q₁) used as weights. 4. Fisher''s Ideal Index: P₀₁ = √(Laspeyres × Paasche) × 100 Geometric mean of Laspeyres and Paasche indices. Called \"ideal\" because it satisfies the time reversal test and factor reversal test.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0ee4d8e6ddb2deb7d58' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'construction-of-index-numbers' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0ee4d8e6ddb2deb7d58-en-106","language":"English","title":"Wholesale Price Index","topic_slug":"wholesale-price-index","definition":"The Wholesale Price Index measures changes in the prices of goods at the wholesale level (before reaching consumers). In India: - Base year: 2011-12 - Covers about 697 commodities - Published by Office of Economic Adviser, Ministry of Commerce - Used to measure general price inflation in the economy Major groups in WPI: 1. Primary Articles (food, non-food, minerals) — weight ~22% 2. Fuel and Power — weight ~13% 3. Manufactured Products — weight ~65%","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0ee4d8e6ddb2deb7d58' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'wholesale-price-index' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0ee4d8e6ddb2deb7d58-en-107","language":"English","title":"Consumer Price Index","topic_slug":"consumer-price-index","definition":"The Consumer Price Index measures changes in the prices of a basket of goods and services typically purchased by consumers. In India (CPI-Combined): - Base year: 2012 = 100 - Compiled by Ministry of Statistics (MoSPI) - Published monthly - Used by RBI for monetary policy decisions Sub-groups in CPI: - Food and Beverages (~45% weight) - Housing - Clothing and Footwear - Fuel and Light - Miscellaneous CPI vs WPI: Feature CPI WPI --- --- --- Coverage Consumer prices Wholesale prices Level Retail Wholesale Services Included Not included Used for Real wages, monetary policy General inflation","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0ee4d8e6ddb2deb7d58' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'consumer-price-index' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0ee4d8e6ddb2deb7d58-en-108","language":"English","title":"Index of Industrial Production","topic_slug":"index-of-industrial-production","definition":"The Index of Industrial Production measures the volume of industrial output (not prices). In India: - Base year: 2011-12 - Covers Mining, Manufacturing, Electricity sectors - Published monthly by MoSPI - Shows growth in industrial production Three components: 1. Mining (weight ~14%) 2. Manufacturing (weight ~77%) 3. Electricity (weight ~8%)","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0ee4d8e6ddb2deb7d58' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'index-of-industrial-production' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0ee4d8e6ddb2deb7d58-en-109","language":"English","title":"Uses of Index Numbers","topic_slug":"uses-of-index-numbers","definition":"Measuring Inflation: CPI and WPI track price changes → helps control inflation 2. Cost of Living: CPI helps workers demand wage revisions based on price changes 3. Real Wage Calculation: Real Wage = Nominal Wage / CPI × 100 4. Economic Comparisons: Compare economic conditions across time periods and countries 5. Business Decisions: Firms use commodity price indices for pricing decisions 6. Government Policy: Budget, monetary policy, and subsidy decisions use index data 7. Deflating Values: Convert nominal GDP to real GDP using price deflators 8. Wage Negotiations: Dearness Allowance (DA) linked to CPI in India Deflating National Income: Real NI = (Nominal NI / Price Index) × 100 --- AHSEC HS 1st Year Economics – Index Numbers chapter.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0ee4d8e6ddb2deb7d58' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'uses-of-index-numbers' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3be0-en-110","language":"English","title":"Market Equilibrium","topic_slug":"market-equilibrium","definition":"Market equilibrium is a situation where the plans of all consumers and firms in the market match, and the market clears. In equilibrium, the aggregate quantity that all firms wish to sell equals the quantity that all the consumers in the market wish to buy: in other words, market supply equals market demand. The price at which equilibrium is reached is called equilibrium price, and the quantity bought and sold at this price is called equilibrium quantity.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3be0' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'market-equilibrium' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3be0-en-111","language":"English","title":"Equilibrium Price and Quantity Determination","topic_slug":"equilibrium-price-and-quantity-determination","definition":"Equilibrium price and quantity can be determined by equating market demand and supply curves. Algebraically, excess demand (ED) can be expressed as ED = D - S, where D is the market demand and S is the market supply. Excess demand will be positive for any price less than the equilibrium price, and excess supply will be positive for any price greater than the equilibrium price.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3be0' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'equilibrium-price-and-quantity-determination' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3be0-en-112","language":"English","title":"Excess Demand and Excess Supply","topic_slug":"excess-demand-and-excess-supply","definition":"Excess demand is a situation where market demand exceeds market supply at a given price. Excess supply is a situation where market supply exceeds market demand at a given price. In a perfectly competitive market, the price will tend to change in response to excess demand or excess supply.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3be0' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'excess-demand-and-excess-supply' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3be0-en-113","language":"English","title":"Market Equilibrium with Fixed Number of Firms","topic_slug":"market-equilibrium-with-fixed-number-of-firms","definition":"In a market with a fixed number of firms, the market supply curve intersects the market demand curve at the equilibrium price and quantity. The equilibrium price and quantity can be determined by equating the market demand and supply curves. The market will move towards the equilibrium point where the quantity that the firms want to sell is equal to the quantity that the consumers want to buy.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3be0' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'market-equilibrium-with-fixed-number-of-firms' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3be0-en-114","language":"English","title":"Out-of-Equilibrium Behaviour","topic_slug":"out-of-equilibrium-behaviour","definition":"In a perfectly competitive market, the \"Invisible Hand\" plays a crucial role in changing the price whenever there is an imbalance in the market. The \"Invisible Hand\" raises the prices in case of excess demand and lowers the prices in case of excess supply.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3be0' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'out-of-equilibrium-behaviour' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3be0-en-115","language":"English","title":"Wage Determination in Labour Market","topic_slug":"wage-determination-in-labour-market","definition":"In a perfectly competitive labour market, the wage rate is determined at the intersection of the demand and supply curves of labour. The demand for labour by a single firm is determined by the marginal revenue product of labour (MRP,). The supply of labour is determined by the wage rate and the marginal product of labour (MP,). The wage rate is determined where the demand for labour equals the supply of labour.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3be0' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'wage-determination-in-labour-market' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3be0-en-116","language":"English","title":"Demand for Labour","topic_slug":"demand-for-labour","definition":"The demand for labour by a single firm is downward sloping due to the law of diminishing marginal product. The firm will always employ labour up to the point where the extra cost of hiring one more unit of labour is equal to the additional benefit earned from that unit. The marginal revenue product of labour (MRP,) is equal to the value of marginal product of labour (VMP,).","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3be0' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'demand-for-labour' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3be0-en-117","language":"English","title":"Supply of Labour","topic_slug":"supply-of-labour","definition":"The supply of labour is determined by the wage rate and the marginal product of labour (MP,). The supply curve of labour is upward sloping, as an increase in the wage rate will lead to an increase in the supply of labour.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3be0' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'supply-of-labour' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3be0-en-118","language":"English","title":"Equilibrium in Labour Market","topic_slug":"equilibrium-in-labour-market","definition":"The equilibrium in the labour market is determined where the demand for labour equals the supply of labour. The wage rate is determined at the intersection of the demand and supply curves of labour. The equilibrium wage rate and quantity of labour can be determined by equating the demand and supply curves of labour.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3be0' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'equilibrium-in-labour-market' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0ed4d8e6ddb2deb7d55-en-119","language":"English","title":"Arithmetic Mean","topic_slug":"arithmetic-mean","definition":"The Arithmetic Mean (AM) is the sum of all observations divided by the number of observations. For ungrouped data: Mean (X̄) = ΣX / n For grouped data (direct method): Mean = Σ(f × m) / Σf Where f = frequency, m = midpoint of class interval Properties of Mean: - Uses all data values - Algebraic treatment is possible - Affected by extreme values (outliers) - Sum of deviations from mean = 0 Merits: Mathematically sound, based on all observations, useful for further calculations. Demerits: Affected by outliers; cannot be calculated for open-end class intervals easily.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0ed4d8e6ddb2deb7d55' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'arithmetic-mean' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0ed4d8e6ddb2deb7d55-en-120","language":"English","title":"Median","topic_slug":"median","definition":"The Median is the value that divides the dataset into two equal halves when data is arranged in ascending or descending order. It is the middle value. For ungrouped data: - If n is odd: Median = value of ((n+1)/2)th item - If n is even: Median = average of (n/2)th and (n/2 + 1)th items For grouped data: Median = L + [(n/2 – cf) / f] × h Where: - L = lower boundary of median class - n = total frequency - cf = cumulative frequency before median class - f = frequency of median class - h = class width Properties: - Not affected by extreme values - Can be determined graphically (from Ogive) - Cannot be used for algebraic manipulation Merits: Not affected by outliers; can be found for open-end class intervals. Demerits: Not based on all observations; less precise.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0ed4d8e6ddb2deb7d55' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'median' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0ed4d8e6ddb2deb7d55-en-121","language":"English","title":"Mode","topic_slug":"mode","definition":"The Mode is the value that occurs most frequently in a dataset. For ungrouped data: The value with the highest frequency. For grouped data: Mode = L + [f1 – f0 / (2f1 – f0 – f2)] × h Where: - L = lower boundary of modal class - f1 = frequency of modal class - f0 = frequency of class before modal class - f2 = frequency of class after modal class - h = class width Modal class: The class with the highest frequency. Properties: - Not affected by extreme values - Can be found for qualitative data too - A dataset may have no mode, one mode (unimodal), or two modes (bimodal) Empirical relationship: Mode = 3 × Median – 2 × Mean (for moderately skewed distributions) Summary Table: Measure Formula Affected by Extremes?","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0ed4d8e6ddb2deb7d55' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'mode' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0ec4d8e6ddb2deb7d53-en-122","language":"English","title":"Meaning of Organisation of Data","topic_slug":"meaning-of-organisation-of-data","definition":"Organisation of data refers to the systematic arrangement of collected data in a form that makes it easy to analyse and interpret. Raw data collected from surveys must be organised before analysis. Steps in data organisation: 1. Editing (checking for errors) 2. Classification (grouping similar data) 3. Tabulation (presenting in tables)","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0ec4d8e6ddb2deb7d53' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'meaning-of-organisation-of-data' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0ec4d8e6ddb2deb7d53-en-123","language":"English","title":"Types of Variables","topic_slug":"types-of-variables","definition":"1. Continuous Variable: A continuous variable can take any value within a given range (including fractions and decimals). Examples: Height (165.5 cm), temperature (37.2°C), weight (62.3 kg). 2. Discrete Variable: A discrete variable can only take specific, countable values (usually integers). Fractional values are not possible. Examples: Number of students (30, 31, 32...), number of children in a family.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0ec4d8e6ddb2deb7d53' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'types-of-variables' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0ec4d8e6ddb2deb7d53-en-124","language":"English","title":"Frequency Distribution","topic_slug":"frequency-distribution","definition":"A frequency distribution is a table that shows the values (or class intervals) and their corresponding frequencies. Simple/Ungrouped Frequency Distribution: Shows individual values and their frequencies. Used when there are few distinct values. Grouped Frequency Distribution: Data is grouped into class intervals. Used when there are many values.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0ec4d8e6ddb2deb7d53' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'frequency-distribution' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0ed4d8e6ddb2deb7d54-en-125","language":"English","title":"Tabular Presentation","topic_slug":"tabular-presentation","definition":"Tabular presentation organises data into rows and columns in a table. It makes data compact and easy to compare. Parts of a table: 1. Table number 2. Title 3. Caption (column headings) 4. Stub (row headings) 5. Body of the table 6. Head note (if any) 7. Footnote and source Types of tables: - Simple table (one characteristic) - Complex table (two or more characteristics)","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0ed4d8e6ddb2deb7d54' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'tabular-presentation' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0ed4d8e6ddb2deb7d54-en-126","language":"English","title":"Diagrammatic Presentation","topic_slug":"diagrammatic-presentation","definition":"Diagrammatic presentation uses visual tools (diagrams, graphs, charts) to display data. It makes data attractive and easy to understand. Types of diagrams: Bar diagrams, pie charts, pictograms, line graphs, histograms. Merits: Visually appealing, easy to compare, can be understood without data literacy. Demerits: Less precise, cannot show exact values.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0ed4d8e6ddb2deb7d54' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'diagrammatic-presentation' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0ed4d8e6ddb2deb7d54-en-127","language":"English","title":"Bar Diagram","topic_slug":"bar-diagram","definition":"A bar diagram uses rectangular bars (horizontal or vertical) whose lengths are proportional to the values they represent. Types: - Simple Bar Diagram: One variable - Multiple (Grouped) Bar Diagram: Two or more variables side by side - Sub-divided (Stacked) Bar Diagram: Bars divided into components - Percentage Bar Diagram: Bars show 100% with component percentages - Horizontal Bar Diagram: Bars drawn horizontally (good for long category names)","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0ed4d8e6ddb2deb7d54' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'bar-diagram' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0ed4d8e6ddb2deb7d54-en-128","language":"English","title":"Pie Diagram","topic_slug":"pie-diagram","definition":"A pie chart is a circular chart divided into sectors. Each sector''s area is proportional to the frequency (or percentage) it represents. Construction: Angle for each component = (Component Value / Total) × 360° Example: If agriculture = 40% of GDP → angle = 0.4 × 360° = 144°","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0ed4d8e6ddb2deb7d54' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'pie-diagram' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0ed4d8e6ddb2deb7d54-en-129","language":"English","title":"Histogram","topic_slug":"histogram","definition":"A histogram is a bar chart for continuous (grouped) data where: - X-axis shows class intervals - Y-axis shows frequency (or frequency density) - Bars are adjacent (no gaps between bars) Key difference from bar chart: In histograms, bars touch each other (no gaps); suitable for continuous data. Area of each bar = Frequency (when class widths are equal) For unequal class widths: Y-axis shows frequency density = Frequency / Class Width","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0ed4d8e6ddb2deb7d54' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'histogram' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0ed4d8e6ddb2deb7d54-en-130","language":"English","title":"Frequency Polygon","topic_slug":"frequency-polygon","definition":"A frequency polygon is a line graph drawn by connecting the midpoints of the top of each bar in a histogram. Construction: 1. Find midpoints of each class interval 2. Plot midpoints vs. frequencies 3. Join points with straight lines 4. Close the polygon at both ends by extending to adjacent midpoints with zero frequency","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0ed4d8e6ddb2deb7d54' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'frequency-polygon' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0ed4d8e6ddb2deb7d54-en-131","language":"English","title":"Frequency Curve","topic_slug":"frequency-curve","definition":"A frequency curve is a smooth curve obtained from a frequency polygon by smoothing out the straight lines. It represents the ideal frequency distribution of a large dataset. Types of frequency curves: - Symmetrical (Bell-shaped / Normal curve) - Positively skewed (tail on right) - Negatively skewed (tail on left) - U-shaped","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0ed4d8e6ddb2deb7d54' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'frequency-curve' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0ed4d8e6ddb2deb7d54-en-132","language":"English","title":"Ogive","topic_slug":"ogive","definition":"An Ogive is a graph of cumulative frequencies plotted against the upper or lower class boundaries. Types: - Less than Ogive: Plot cumulative frequency against upper class boundary (rises from left to right) - More than Ogive: Plot cumulative frequency against lower class boundary (falls from left to right) Use: Finding median, quartiles, and percentiles graphically. The X-value at the intersection of Less-than and More-than Ogives = Median.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0ed4d8e6ddb2deb7d54' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'ogive' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a19e0ed4d8e6ddb2deb7d54-en-133","language":"English","title":"Time Series Graph","topic_slug":"time-series-graph","definition":"A time series graph (line graph) shows how a variable changes over time. - X-axis: Time (years, months, quarters) - Y-axis: Value of the variable - Points are joined by straight lines Example: GDP growth rate of India from 2010 to 2020. Uses: - Identify trends (upward, downward, cyclical) - Seasonal variation analysis - Economic forecasting --- AHSEC HS 1st Year Economics – Presentation of Data chapter.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a19e0ed4d8e6ddb2deb7d54' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'time-series-graph' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bdb-en-134","language":"English","title":"Meaning of Production","topic_slug":"meaning-of-production","definition":"Production is the process of transforming inputs (factors of production) into outputs (goods and services). It creates utility and adds value to resources. Factors of Production: 1. Land: Natural resources 2. Labour: Human effort (physical and mental) 3. Capital: Man-made means of production (machines, tools, buildings) 4. Entrepreneurship: Organising and risk-taking","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bdb' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'meaning-of-production' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bdb-en-135","language":"English","title":"Production Function","topic_slug":"production-function","definition":"A production function shows the technical relationship between inputs used and the output produced, given the state of technology. Q = f(L, K) where Q = output, L = labour, K = capital The production function specifies the maximum output obtainable from a given combination of inputs.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bdb' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'production-function' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bdb-en-136","language":"English","title":"Short Run","topic_slug":"short-run","definition":"The short run is a period of time in which at least one factor of production is fixed. Firms can only change variable inputs (usually labour) to change output. - Fixed inputs: Capital (machines, factory size) - Variable inputs: Labour, raw materials","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bdb' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'short-run' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bdb-en-137","language":"English","title":"Long Run","topic_slug":"long-run","definition":"The long run is a period of time in which all factors of production can be varied. There are no fixed factors. In the long run, firms can change both labour and capital, change the scale of production, and enter or exit the industry.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bdb' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'long-run' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bdb-en-138","language":"English","title":"Total Product","topic_slug":"total-product","definition":"Total Product is the total quantity of output produced by a firm using given quantities of inputs. TP = Sum of Marginal Products TP initially increases at an increasing rate, then at a diminishing rate, reaches maximum, and may fall.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bdb' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'total-product' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bdb-en-139","language":"English","title":"Marginal Product","topic_slug":"marginal-product","definition":"Marginal Product is the additional output produced by employing one more unit of the variable input. MP = ΔTP / ΔL Relationship between TP, AP, and MP: - When MP AP → AP is rising - When MP = AP → AP is at its maximum - When MP < AP → AP is falling - When MP = 0 → TP is maximum - When MP is negative → TP is falling","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bdb' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'marginal-product' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bdb-en-140","language":"English","title":"Law of Variable Proportions","topic_slug":"law-of-variable-proportions","definition":"The Law of Variable Proportions states that as we increase the quantity of one variable input (keeping other inputs fixed), the total product first increases at an increasing rate, then at a diminishing rate, and finally may decrease. Three stages: 1. Stage I (Increasing Returns): MP rises; TP increases at increasing rate 2. Stage II (Diminishing Returns): MP falls but positive; TP increases at diminishing rate → Rational production zone 3. Stage III (Negative Returns): MP is negative; TP falls Assumptions: - Technology is constant - Only one input is variable - All units of variable input are homogeneous","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bdb' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'law-of-variable-proportions' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bdb-en-141","language":"English","title":"Returns to Scale","topic_slug":"returns-to-scale","definition":"Returns to Scale examine what happens to output when ALL inputs are increased proportionately (long run concept). Types: - Increasing Returns to Scale (IRS): Output increases more than proportionately → economies of scale (specialisation, indivisibility of factors) - Constant Returns to Scale (CRS): Output increases in the same proportion as inputs - Decreasing Returns to Scale (DRS): Output increases less than proportionately → managerial inefficiency, resource scarcity --- AHSEC HS 1st Year Economics – Production chapter based on NCERT Class 11.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bdb' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'returns-to-scale' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bd9-en-142","language":"English","title":"Production and Costs","topic_slug":"production-and-costs","definition":"Production is the process by which inputs are transformed into output. A firm acquires different inputs like labour, machines, land, raw materials, etc. to produce output. The output can be consumed by consumers or used by other firms for further production. A production function is a relationship between inputs used and output produced by the firm. It gives the maximum quantity of output that can be produced for various quantities of inputs used.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bd9' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'production-and-costs' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bd9-en-143","language":"English","title":"Factors of Production","topic_slug":"factors-of-production","definition":"The inputs that a firm uses in the production process are called factors of production. In order to produce output, a firm may require any number of different inputs. For the time being, here we consider a firm that produces output using only two factors of production - labour and capital.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bd9' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'factors-of-production' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bd9-en-144","language":"English","title":"Production Function","topic_slug":"production-function","definition":"A production function is defined for a given technology. If the technology improves, the maximum levels of output obtainable for different input combinations increase. We may write the production function as q=f(L,K), where Lis labour and K is capital and q is the maximum output that can be produced.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bd9' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'production-function' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bd9-en-145","language":"English","title":"Isoquant","topic_slug":"isoquant","definition":"An isoquant is the set of all possible combinations of the two inputs that yield the same maximum possible level of output. Each isoquant represents a particular level of output and is labelled with that amount of output. Isoquants are negatively sloped, meaning that with greater amount of one input, the same level of output can be produced only using lesser amount of the other.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bd9' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'isoquant' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bd9-en-146","language":"English","title":"Short Run and Long Run","topic_slug":"short-run-and-long-run","definition":"Before we begin with any further analysis, it is important to discuss two concepts - the short run and the long run. The short run is a period of time in which at least one input is fixed in quantity. The long run is a period of time in which all inputs can be varied.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bd9' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'short-run-and-long-run' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bd9-en-147","language":"English","title":"Cost of Production","topic_slug":"cost-of-production","definition":"The cost of production is the amount of money a firm has to pay for the inputs it uses. The cost of production includes the cost of labour, capital, raw materials, etc. The cost of production is an important concept in economics as it helps firms to determine their production levels and prices.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bd9' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'cost-of-production' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bd9-en-148","language":"English","title":"Types of Costs","topic_slug":"types-of-costs","definition":"There are two types of costs - fixed costs and variable costs. Fixed costs are those costs that remain the same even if the level of production changes. Variable costs are those costs that change with the level of production.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bd9' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'types-of-costs' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bd9-en-149","language":"English","title":"Average and Marginal Costs","topic_slug":"average-and-marginal-costs","definition":"Average cost is the total cost divided by the number of units produced. Marginal cost is the change in total cost resulting from a one-unit increase in output. Average and marginal costs are important concepts in economics as they help firms to determine their production levels and prices.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bd9' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'average-and-marginal-costs' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
