UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bde-en-170","language":"English","title":"What is Economics?","topic_slug":"what-is-economics","definition":"Economics is the study of man in the ordinary business of life. It involves the study of activities in consumption, production, and distribution. Economics is concerned with the basic problems facing a country. It involves the study of how people and society choose to employ scarce resources that could have alternative uses in order to produce various commodities that satisfy their wants and to distribute them for consumption among various persons and groups in society. The definition of economics is: \"Economics is the study of how people and society choose to employ scarce resources that could have alternative uses in order to produce various commodities that satisfy their wants and to distribute them for consumption among various persons and groups in society.\"","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bde' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'what-is-economics' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bde-en-171","language":"English","title":"Economic Activities","topic_slug":"economic-activities","definition":"Economic activities are ones that are undertaken for a monetary gain. These activities include consumption, production, and distribution. A person is gainfully employed in an economic activity when they are engaged in any of these activities. Examples of economic activities include buying goods, selling goods, producing goods, and providing services.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bde' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'economic-activities' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bde-en-172","language":"English","title":"Scarcity","topic_slug":"scarcity","definition":"Scarcity is the root of all economic problems. It arises because the things that satisfy our wants are limited in availability. Scarcity can be caused by the limited availability of resources or the limited wants of individuals. Examples of scarcity include the long queues at railway booking counters, crowded buses and trains, shortage of essential commodities, and the rush to get a ticket to watch a new film.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bde' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'scarcity' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bde-en-173","language":"English","title":"Types of Scarcity","topic_slug":"types-of-scarcity","definition":"Scarcity can be classified into three types: physical scarcity, economic scarcity, and social scarcity. Physical scarcity arises due to the limited availability of resources. Economic scarcity arises due to the limited wants of individuals. Social scarcity arises due to the limited availability of resources and the limited wants of individuals.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bde' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'types-of-scarcity' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bde-en-174","language":"English","title":"Economic Activities of Individuals","topic_slug":"economic-activities-of-individuals","definition":"Economic activities of individuals include consumption, production, and distribution. A person is a consumer when they buy goods or services. A person is a producer when they produce goods or services. A person is a seller when they sell goods or services. A person is an employer when they employ others to work for them.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bde' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'economic-activities-of-individuals' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bde-en-175","language":"English","title":"Economic Activities of the Government","topic_slug":"economic-activities-of-the-government","definition":"Economic activities of the government include taxation, public expenditure, and regulation. The government collects taxes from its citizens to finance its activities. The government also regulates economic activities to ensure that they are carried out in a fair and equitable manner.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bde' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'economic-activities-of-the-government' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bde-en-176","language":"English","title":"The Study of Economics","topic_slug":"the-study-of-economics","definition":"The study of economics involves the analysis of economic data and the formulation of policies to solve economic problems. Economics is a social science that deals with the study of human behavior and the economy. The study of economics involves the use of statistical tools and techniques to analyze economic data.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bde' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'the-study-of-economics' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bde-en-177","language":"English","title":"Statistics in Economics","topic_slug":"statistics-in-economics","definition":"Statistics is a branch of mathematics that deals with the collection, analysis, interpretation, and presentation of numerical data. Statistics is used in economics to analyze economic data and to formulate policies to solve economic problems. The use of statistics in economics involves the collection of data, the presentation of data in tabular, diagrammatic, and graphic forms, and the analysis and interpretation of data.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bde' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'statistics-in-economics' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
UPDATE chapters SET published_topics = json_insert(COALESCE(NULLIF(published_topics, ''), '[]'), '$[#]', json('{"id":"topic-6a1f19fbcee3667f3ecc3bde-en-178","language":"English","title":"Qualitative and Quantitative Data","topic_slug":"qualitative-and-quantitative-data","definition":"Qualitative data is information that describes attributes of a single person or a group of persons. Quantitative data is information that can be measured and expressed in numerical terms. Examples of qualitative data include beauty, intelligence, income earned, and marks in a subject. Examples of quantitative data include the production of rice in India, the increase in production of rice, and the prices of goods and services.","definition_status":"ok","status":"published"}')), updated_at = unixepoch() WHERE id = '6a1f19fbcee3667f3ecc3bde' AND status = 'published' AND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(NULLIF(published_topics, ''), '[]')) AS existing WHERE json_extract(existing.value, '$.topic_slug') = 'qualitative-and-quantitative-data' AND COALESCE(json_extract(existing.value, '$.language'), 'English') = 'English');
